#!/usr/bin/env node
/* Books-2 batch2-part2 ENT wave: Dhingra ENT 8th topic map, own words, new MCQs only. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF = "Dhingra Diseases of ENT 8th Edition (topic map; text rewritten, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp) { return { id, q, o, a, exp, r, kp }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
function tbl(cols, rows) { return { kind: "table", cols, rows }; }
function cmp(lt, lp, rt, rp) { return { kind: "compare", left: { title: lt, points: lp }, right: { title: rt, points: rp } }; }
const M = [];
function add(id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs }); }

add("ent-external-ear", "Diseases of the external ear", "diseases_of_the_external_ear", "Diseases of the External Ear",
 ["Otitis externa", "Wax impaction", "Malignant otitis externa", "Perichondritis"],
 [step("The **external ear** collects sound through the pinna and external auditory canal to the tympanic membrane. The outer canal is cartilaginous with glands and hair, the inner canal is bony and exquisitely tender, which explains pain patterns in disease. Congenital atresia, prominent ears and microtia matter cosmetically and for hearing development in children.", "The pinna and canal funnel sound to the drum. The bony inner canal hurts easily. Birth canal defects affect appearance and hearing development."),
  step("**Otitis externa** inflames canal skin, often after water exposure or cotton bud trauma, causing itch then severe pain worsened by tragus pressure or jaw movement. Discharge, canal swelling and debris block hearing temporarily. Pseudomonas dominates in swimmers and diabetics, while Aspergillus and Candida cause itchy fungal disease with visible spores after prolonged topical antibiotics.", "Swimmer's ear hurts when the tragus is pressed. Pseudomonas follows water exposure; fungi follow long topical antibiotics. Pain out of proportion needs care."),
  step("Impacted **wax** is treated only when symptomatic, causing blockage, deafness or masking the drum, and removed by syringing only with an intact drum and no infection history, or by microsuction and instruments under vision. Auricular haematoma from trauma must be drained and compressed, otherwise repeated bleeding destroys cartilage into cauliflower ear.", "Treat wax only when it blocks or deafs. Never syringe a perforated drum blindly. Drain and compress ear haematomas to save cartilage shape."),
  step("**Malignant (necrotising) otitis externa** is a skull base osteomyelitis of the canal in elderly diabetics or immunosuppressed patients, almost always pseudomonal. Nocturnal deep pain, granulations at the bone cartilage junction and cranial nerve palsies signal spread. It demands prolonged antipseudomonal therapy and imaging, never simple ear drops alone.", "In elderly diabetics, deep night pain with canal granulations means skull base infection until disproven. That needs systemic antipseudomonal treatment and scans."),
  step("Perichondritis infects pinna cartilage after trauma, piercing or burns, sparing the lobule which has no cartilage, while relapsing polychondritis is autoimmune and recurrent. Canal furuncle is a staphylococcal hair follicle abscess of the outer canal. Herpes zoster oticus (Ramsay Hunt) blisters the concha with facial palsy when varicella zoster reactivates in the geniculate ganglion.", "Lobule sparing points to cartilage disease of the pinna. Ramsay Hunt blisters the ear and paralyses the face from shingles reactivation.")],
 ["Tragus tenderness with normal drum means otitis externa", "Malignant otitis externa: elderly diabetic, night pain, pseudomonas, skull base", "Auricular haematoma needs drainage plus pressure to prevent cauliflower ear", "Never syringe an ear with perforation or past mastoid surgery"],
 "Canal skin maceration and microtrauma let Pseudomonas or fungi invade; in diabetics microangiopathy and impaired immunity let infection breach cartilage into skull base bone. Auricular blood separates perichondrium from cartilage, starving it toward necrotic deformity.",
 ["Otitis externa versus acute otitis media (drum appearance and tragus sign)", "Perichondritis (sparing lobule) versus cellulitis of lobule", "Benign canal exostoses (surfer ear) versus osteoma"],
 ["Otoscopy and microscopy with canal toilet", "Culture of discharge; CT/MRI skull base when malignant disease suspected", "Audiometry when canal disease deafens"],
 [mcq("bk2-ent-001", "Severe ear pain worsened by pressing the tragus, with a swollen canal and normal drum, indicates what?", ["Acute otitis media", "Otitis externa", "Otosclerosis", "Meniere disease"], 1, "Canal inflammation hurts on tragus pressure and pinna traction, and the drum stays normal behind oedematous canal. Middle ear disease instead bulges the drum without tragus tenderness.", ["Incorrect. Middle ear pain spares tragus pressure and bulges the drum.", "Correct. Tragus tenderness plus canal swelling means otitis externa.", "Incorrect. Otosclerosis deafens painlessly with normal canal.", "Incorrect. Meniere causes vertigo and aural fullness, not canal pain."], "Pain on tragus press: think canal, not middle ear."),
  mcq("bk2-ent-002", "Elderly diabetic with deep nocturnal ear pain and granulations at the canal floor most likely has what?", ["Furunculosis", "Malignant otitis externa", "Wax impaction", "Eczematous otitis"], 1, "Necrotising otitis externa is pseudomonal skull base osteomyelitis of elderly diabetics: night pain, junction granulations, cranial nerve risk. It needs systemic antipseudomonal therapy.", ["Incorrect. Furuncle is a localised outer canal staphylococcal boil.", "Correct. Diabetic night pain with granulations means malignant otitis externa.", "Incorrect. Wax blocks quietly without granulations.", "Incorrect. Eczema itches and scales without bone invasion."], "Old diabetic, night pain, granulations: skull base infection until disproven."),
  mcq("bk2-ent-003", "Wax removal by syringing is contraindicated when which condition exists?", ["Impacted hard wax", "Tympanic membrane perforation", "Bilateral wax", "Itchy canal"], 1, "Syringing a perforated ear drives infected water into the middle ear and mastoid. Use microsuction under vision instead when the drum is perforated or surgery history exists.", ["Incorrect. Hard symptomatic wax is itself an indication with intact drum.", "Correct. Perforation forbids blind syringing.", "Incorrect. Both ears may be cleared safely if drums intact.", "Incorrect. Itch alone needs diagnosis before any clearing."], "No drum, no syringe: clear under vision."),
  mcq("bk2-ent-004", "Blisters on the concha with ipsilateral facial palsy define which syndrome?", ["Bell palsy alone", "Ramsay Hunt syndrome", "Gradenigo syndrome", "Frey syndrome"], 1, "Varicella zoster reactivation in the geniculate ganglion causes Ramsay Hunt: conchal vesicles, facial palsy and ear pain, often with vertigo. Early antivirals and steroids help recovery.", ["Incorrect. Bell palsy lacks vesicles and ear lesions.", "Correct. Vesicles plus facial palsy mean Ramsay Hunt.", "Incorrect. Gradenigo adds abducens palsy and retro-orbital pain from petrositis.", "Incorrect. Frey is gustatory sweating after parotid surgery."], "Ear blisters plus weak face equals shingles of the facial nerve."),
  mcq("bk2-ent-005", "A boxer with a tense fluctuant pinna swelling after a blow needs what urgently?", ["Reassurance only", "Drainage and firm pressure dressing", "Topical steroids alone", "Canal syringing"], 1, "Auricular haematoma separates perichondrium from cartilage; undrained blood necroses cartilage into cauliflower ear. Aspiration or incision plus compression prevents deformity.", ["Incorrect. Untreated haematoma permanently deforms the ear.", "Correct. Drain and compress to save cartilage.", "Incorrect. Steroids do not remove the blood collection.", "Incorrect. Canal cleaning is irrelevant to pinna haematoma."], "Drain it and press it, or the ear crumples."),
  mcq("bk2-ent-006", "Fungal otitis externa (otomycosis) is most often precipitated by what?", ["Swimming alone", "Prolonged topical antibiotic ear drops", "Wax removal", "Hearing aid removal"], 1, "Long topical antibiotics suppress bacteria and let Aspergillus and Candida flourish, giving itchy canal debris with visible fungal elements. Thorough toilet and antifungal therapy cure it.", ["Incorrect. Water favours bacterial Pseudomonas disease mainly.", "Correct. Prolonged antibiotic drops breed otomycosis.", "Incorrect. Clearing wax under vision does not cause fungal disease.", "Incorrect. Hearing aids may macerate but drops are classic precipitant."], "Itchy ear after weeks of drops: look for fungus."),
  mcq("bk2-ent-007", "Perichondritis of the pinna characteristically spares which part?", ["Helix", "Ear lobule", "Antihelix", "Tragus"], 1, "The lobule contains no cartilage, so cartilage infection (perichondritis) spares it while bacterial cellulitis involves it. Pseudomonas after piercing is typical and cartilage needs prompt systemic cover.", ["Incorrect. Helix is cartilage and inflames.", "Correct. No cartilage in lobule, so perichondritis spares it.", "Incorrect. Antihelix cartilage is involved.", "Incorrect. Tragus cartilage can be involved."], "Sore pinna sparing lobule equals cartilage disease."),
  mcq("bk2-ent-008", "Bony canal swellings in a cold water swimmer narrowing both canals are most likely what?", ["Osteoma (solitary)", "Exostoses (surfer ear)", "Canal cholesteatoma", "Foreign body"], 1, "Cold water induces multiple bilateral bony exostoses narrowing canals, trapping wax and water. Solitary unilateral pedunculated bony mass is osteoma instead. Surgery only when symptomatic.", ["Incorrect. Osteoma is usually solitary and unilateral.", "Correct. Multiple bilateral bony humps in swimmers are exostoses.", "Incorrect. Cholesteatoma gives keratin debris and erosion, not native bone humps.", "Incorrect. Foreign bodies are objects, not fixed bony walls."], "Cold water plus bilateral bony narrowing means surfer ear."),
  mcq("bk2-ent-009", "Canal furuncle causes pain mainly located where and from what infection?", ["Inner bony canal; viral", "Outer cartilaginous canal hair follicle; staphylococcal", "Middle ear; pneumococcal", "Mastoid; pseudomonal"], 1, "Hair follicles exist only in outer cartilaginous canal, so staphylococcal furuncles sit there and hurt on jaw movement. Inner bony canal has no follicles. Most settle with analgesia and local care.", ["Incorrect. Inner canal lacks hair follicles and viral boils.", "Correct. Outer canal follicle staphylococcal abscess is a furuncle.", "Incorrect. That describes otitis media instead.", "Incorrect. Mastoid pseudomonas disease is malignant otitis pattern."], "Boils grow only where hairs grow: outer canal."),
  mcq("bk2-ent-010", "First step for a live insect in the ear canal is what?", ["Syringe immediately", "Immobilise with oil or alcohol then remove under vision", "Push with cotton bud", "Ignore until it exits"], 1, "Killing or immobilising the insect with oil prevents painful movement and bites, then remove by suction or forceps under vision. Cotton buds push objects deeper and injure drums.", ["Incorrect. Syringing a live insect causes frantic movement and pain.", "Correct. Still it with oil, then remove under vision.", "Incorrect. Buds push deeper and perforate drums.", "Incorrect. Retained insects damage canal and drum."], "Still the insect first, then lift it out under sight.")]);

add("ent-aom-ome", "Acute otitis media and otitis media with effusion", "acute_otitis_media_and_effusion", "Acute Otitis Media and Otitis Media with Effusion",
 ["Acute otitis media", "Glue ear", "Bulging tympanic membrane", "Tympanostomy tubes"],
 [step("**Acute otitis media** is middle ear infection behind an intact drum, peaking in young children whose short horizontal Eustachian tubes admit nasopharyngeal bacteria after viral colds. Streptococcus pneumoniae, Haemophilus influenzae and Moraxella catarrhalis dominate. Otalgia, fever, a bulging red drum and lost landmarks make the diagnosis; a merely red drum in a crying child does not.", "Toddlers get middle ear infections after colds through short Eustachian tubes. Bulging drum plus pain and fever diagnose it, not mere redness."),
  step("Most acute otitis media resolves spontaneously, so guidelines use analgesia and watchful waiting for mild older cases, with antibiotics for infants, bilateral, severe or otorrhoea cases (local protocol decides agents). Decongestants and antihistamines do not help. Persistent bulge risks perforation, which paradoxically relieves pain as pus drains.", "Many ear infections settle alone. Pain relief first; antibiotics for young, bilateral or severe cases. Nasal sprays do not clear middle ears."),
  step("**Otitis media with effusion (glue ear)** is sterile fluid behind an intact drum without acute infection, causing conductive deafness, speech delay and school difficulty in children. The drum looks dull, retracted or with visible fluid level and bubbles. Most effusions clear in three months, so watchful waiting precedes intervention.", "Glue ear is quiet fluid deafening children without infection. Most clears within three months, so watch before operating."),
  step("Persistent bilateral effusion with hearing loss beyond three months, speech or developmental impact, leads to hearing tests and consideration of **ventilation tubes (grommets)**, which equalise pressure while inserted but extrude spontaneously. Adenoidectomy helps selected older children with nasal obstruction. Autoinflation devices aid some cooperative children.", "Lasting glue ear with deafness earns hearing tests and possible grommets. Tubes fall out alone. Big adenoids blocking the nose may need removal too.", tbl(["Feature", "Acute otitis media", "Otitis media with effusion"], [["Pain and fever", "Present, acute", "Absent"], ["Drum", "Bulging, red, opaque", "Dull, retracted, fluid level"], ["Hearing", "Mild loss during illness", "Persistent conductive loss"], ["Treatment", "Analgesia, selected antibiotics", "Watch 3 months, then tubes if deaf"]])),
  step("Recurrent acute otitis media (three in six months or four in a year) prompts ENT referral, hearing assessment and risk reduction: smoke free home, breastfeeding support and pneumococcal vaccination status. Effusion in an adult, especially unilateral, mandates nasopharyngeal examination to exclude obstructing tumour, a classic exam trap.", "Repeated infections need referral and hearing checks. One sided glue ear in an adult means examine the nasopharynx for tumour.")],
 ["Bulging drum diagnoses AOM; red drum alone does not", "Glue ear: watch three months before grommets", "Unilateral effusion in adult equals nasopharynx examination", "Analgesia is treatment for every child with AOM"],
 "Viral upper airway inflammation swells the Eustachian tube, trapping bacteria in middle ear fluid under pressure. Effusion persists when tube dysfunction keeps the ear under-ventilated after infection or from adenoid obstruction.",
 ["AOM versus otitis externa (tragus sign, drum)", "OME versus chronic suppurative otitis media (perforation)", "Unilateral adult effusion: tumour versus simple dysfunction"],
 ["Otoscopy (pneumatic where available) and tympanometry", "Age appropriate audiometry for persistent effusion", "Nasopharyngoscopy for adult unilateral effusion"],
 [mcq("bk2-ent-011", "Which otoscopic finding best diagnoses acute otitis media?", ["Red drum in crying child", "Bulging opaque drum with lost landmarks", "Retracted drum with fluid level", "Perforated drum with pus"], 1, "Bulging from pus under pressure is the diagnostic sign of AOM. Redness alone occurs with crying and fever, fluid levels mark effusion, and perforation indicates a later ruptured stage.", ["Incorrect. Redness alone is non specific in crying children.", "Correct. Bulging opaque drum diagnoses acute otitis media.", "Incorrect. That is effusion without acute infection.", "Incorrect. Perforation is rupture after AOM, not its defining sign."], "Bulge makes the diagnosis, not blush."),
  mcq("bk2-ent-012", "Glue ear in a 4 year old persisting 4 months with 30 dB loss and speech delay needs what next?", ["Immediate antibiotics course", "Hearing assessment and grommet consideration", "Reassurance for 2 more years", "Topical ear drops"], 1, "Bilateral effusion beyond three months with hearing and developmental impact meets criteria for audiology and ventilation tube discussion. Antibiotics and drops do not clear chronic effusion.", ["Incorrect. Antibiotics do not resolve established glue ear.", "Correct. Test hearing and consider grommets.", "Incorrect. Years of deafness harm speech development.", "Incorrect. Drops cannot reach fluid behind intact drum."], "Three months of deaf glue ear: test and tube."),
  mcq("bk2-ent-013", "Unilateral otitis media with effusion in a 55 year old man mandates which examination?", ["Pure tone audiogram only", "Nasopharyngeal examination", "Mastoid X ray", "Allergy testing"], 1, "Adult unilateral effusion suggests Eustachian tube orifice obstruction, classically nasopharyngeal carcinoma, requiring direct nasopharyngeal inspection and imaging as indicated.", ["Incorrect. Audiogram confirms loss but misses the cause.", "Correct. Examine the nasopharynx for obstructing tumour.", "Incorrect. Mastoid films do not find nasopharyngeal lesions.", "Incorrect. Allergy does not explain unilateral adult effusion."], "One sided adult glue ear: look at the nasopharynx."),
  mcq("bk2-ent-014", "Most common bacterial cause of acute otitis media in children is which organism group?", ["Pseudomonas aeruginosa", "Streptococcus pneumoniae and Haemophilus influenzae", "Staphylococcus aureus skin flora", "Anaerobes"], 1, "Pneumococcus, non typable Haemophilus influenzae and Moraxella catarrhalis from the nasopharynx cause most childhood AOM. Pseudomonas belongs to canal and chronic perforated disease.", ["Incorrect. Pseudomonas causes otitis externa and chronic discharge.", "Correct. Pneumococcus and Haemophilus dominate AOM.", "Incorrect. Staph causes canal furuncles mainly.", "Incorrect. Anaerobes feature in chronic mastoid disease."], "Child middle ear bugs come from the nasopharynx."),
  mcq("bk2-ent-015", "A grommet (ventilation tube) helps glue ear by what mechanism?", ["Delivering antibiotics to middle ear", "Ventilating middle ear bypassing Eustachian tube", "Sealing perforations permanently", "Removing adenoids"], 1, "Tubes equalise middle ear pressure and drain effusion through the drum while patent, restoring hearing until natural extrusion. They do not medicate or permanently seal the drum.", ["Incorrect. Tubes ventilate; they are not drug devices.", "Correct. Ventilation bypasses the failing Eustachian tube.", "Incorrect. The hole closes after extrusion usually.", "Incorrect. Adenoidectomy is a separate operation."], "Grommets are vents, not medicine ports."),
  mcq("bk2-ent-016", "Recurrent acute otitis media is defined approximately as what?", ["Two episodes in 2 years", "Three in 6 months or four in a year", "One episode with perforation", "Monthly effusion checks"], 1, "Three episodes in six months or four in twelve months (with one recent) define recurrent AOM prompting referral, hearing checks and preventive measures. Single perforation alone does not define it.", ["Incorrect. Two in two years is ordinary childhood frequency.", "Correct. Three in six or four in twelve months.", "Incorrect. One ruptured episode is severity, not recurrence pattern.", "Incorrect. Effusion surveillance is glue ear follow up."], "Three in six, four in twelve: recurrent."),
  mcq("bk2-ent-017", "Why does AOM perforation often relieve the child's pain abruptly?", ["Infection cured instantly", "Pus drainage releases middle ear pressure", "Drum healing completes", "Fever breaks by coincidence"], 1, "Bulging pus under pressure causes severe pain; spontaneous perforation vents pus, relieving pain while otorrhoea begins. Infection still needs follow up and drum healing checks.", ["Incorrect. Drainage relieves pressure; infection persists initially.", "Correct. Venting pus drops pressure and pain.", "Incorrect. Healing takes days to weeks after.", "Incorrect. Relief tracks drainage mechanically."], "Pop and drain: pressure off, pain off."),
  mcq("bk2-ent-018", "Tympanometry in glue ear typically shows which pattern?", ["Normal peaked curve", "Flat type B curve with normal canal volume", "Flat curve with huge canal volume", "Type Ad hypermobile curve"], 1, "Fluid filled middle ear cannot comply, giving flat type B tympanogram with normal canal volume (intact drum). Large volume flat curve instead suggests perforation or patent tube.", ["Incorrect. Peaked curve is normal aerated ear.", "Correct. Flat B with normal volume means effusion.", "Incorrect. Huge volume means open perforation or tube.", "Incorrect. Hypermobile curves occur in flaccid drums or ossicular discontinuity."], "Flat B, normal volume: fluid. Flat B, huge volume: hole."),
  mcq("bk2-ent-019", "Which measure does NOT help recurrent childhood otitis media prevention?", ["Smoke free environment", "Pneumococcal vaccination", "Prolonged prophylactic decongestants", "Breastfeeding support"], 2, "Decongestants and antihistamines show no benefit for otitis media prevention or effusion clearance. Smoke avoidance, vaccination and breastfeeding reduce risk modestly.", ["Incorrect. Smoke exposure raises recurrence; avoiding helps.", "Incorrect. Vaccination reduces pneumococcal episodes.", "Correct. Decongestants do not prevent otitis media.", "Incorrect. Breastfeeding is protective."], "Sprays and syrups do not keep ears clear."),
  mcq("bk2-ent-020", "Adenoidectomy aids glue ear mainly in which selected children?", ["All infants under 1 year", "Older children with adenoid hypertrophy and nasal obstruction", "Children with perforated drums", "Adults with effusion"], 1, "Adenoidectomy benefits selected older children where enlarged adenoids obstruct the nasopharynx and Eustachian orifices, often combined with tube surgery on recurrence. It is not routine for infants.", ["Incorrect. Infants are not candidates for this indication.", "Correct. Older children with obstructive adenoids benefit.", "Incorrect. Perforation is chronic suppurative disease pathway.", "Incorrect. Adult effusion needs tumour exclusion first."], "Big blocking adenoids in older children: removal helps ears.")]);

add("ent-csom", "Chronic otitis media and cholesteatoma", "chronic_otitis_media_and_cholesteatoma", "Chronic Otitis Media and Cholesteatoma",
 ["Chronic suppurative otitis media", "Cholesteatoma", "Atticoantral disease", "Tympanoplasty"],
 [step("**Chronic otitis media** means persistent middle ear and mastoid inflammation with drum perforation and discharge lasting weeks. Safe (tubotympanic) disease has a central perforation with mucosal infection and conductive loss but low complication risk. Unsafe (atticoantral) disease has attic or marginal perforation harbouring cholesteatoma that erodes bone toward brain, labyrinth and facial nerve.", "Chronic ear disease is perforation plus lasting discharge. Central holes are safer; attic disease with cholesteatoma erodes toward brain and balance organs."),
  step("**Cholesteatoma** is keratinising squamous epithelium growing into the middle ear and mastoid, trapping desquamated keratin that expands, infects (often Pseudomonas and anaerobes) and erodes ossicles, labyrinth and tegmen. Acquired disease follows retraction pockets from Eustachian dysfunction sucking the drum attic inward, or migration through marginal perforations. Congenital cholesteatoma grows behind an intact drum in children.", "Cholesteatoma is skin growing in the wrong place, trapping keratin and eroding bone. Retraction pockets from poor ventilation create most acquired cases."),
  step("Patients report painless foul discharge unresponsive to drops, conductive deafness and sometimes vertigo, facial weakness or headache warning of complications. Otoscopy shows attic crust or white keratin mass. CT temporal bone maps erosion; diffusion MRI detects residual pearls after surgery. Audiometry grades conductive versus sensorineural loss.", "Foul painless discharge ignoring drops plus attic white mass means cholesteatoma. Scans map erosion before surgery."),
  step("Treatment is surgical: **mastoidectomy** removes disease and creates a safe dry ear, with tympanoplasty reconstructing drum and ossicles when possible. Canal wall up preserves anatomy but risks hidden recurrence needing second look; canal wall down exteriorises disease for surveillance at cost of a mastoid cavity needing lifelong care. Medical therapy only temporises.", "Only surgery removes cholesteatoma. Wall up hides recurrence; wall down needs cavity care. Drops alone never cure it.", cmp("Safe CSOM", ["Central perforation", "Mucosal disease, watery discharge", "Conductive loss, low complications", "Aural toilet, drops, myringoplasty"], "Unsafe CSOM", ["Attic or marginal perforation", "Cholesteatoma, foul discharge", "Bone erosion, brain and labyrinth risk", "Mastoid surgery mandatory"])),
  step("Safe central perforations are kept dry (water precautions), treated with toilet and topical therapy for discharge, then offered myringoplasty once dry, improving hearing and infection resistance. Children with bilateral disease and deafness get hearing support meanwhile. Any chronic ear with vertigo, palsy or fever becomes urgent.", "Keep safe perforations dry, clean infected flares, close dry holes surgically. Vertigo or facial weakness with chronic ear is urgent.")],
 ["Attic perforation plus foul discharge equals cholesteatoma until disproven", "Cholesteatoma is skin in middle ear eroding bone; surgery only cure", "Central perforation is safe; marginal and attic are unsafe", "Chronic ear plus vertigo or facial palsy means complication now"],
 "Negative middle ear pressure retracts the lax attic drum into a pocket that traps keratin, while enzymes and infected debris erode bone. Expanding keratin pearls destroy ossicles and can fistulise the labyrinth or expose dura.",
 ["Safe versus unsafe CSOM by perforation site", "Cholesteatoma versus canal keratosis or wax", "Congenital cholesteatoma (intact drum) versus acquired retraction pocket"],
 ["Microscopic otoscopy and aural toilet", "CT temporal bone; diffusion weighted MRI for residual disease", "Pure tone audiometry"],
 [mcq("bk2-ent-021", "An attic perforation with foul discharge and white keratin debris indicates what?", ["Safe tubotympanic disease", "Cholesteatoma (unsafe disease)", "Glue ear", "Otitis externa"], 1, "Attic or marginal perforations harbour cholesteatoma: keratinising epithelium eroding bone with foul pseudomonal discharge. It mandates surgical removal, unlike safe central disease.", ["Incorrect. Safe disease uses central perforations.", "Correct. Attic keratin disease is cholesteatoma.", "Incorrect. Glue ear has intact drum without discharge.", "Incorrect. Canal disease spares attic drum lesions."], "Attic hole plus foul keratin: unsafe ear."),
  mcq("bk2-ent-022", "Cholesteatoma is best defined histologically as what?", ["Middle ear cancer", "Keratinising squamous epithelium in middle ear trapping keratin", "Cholesterol crystal granuloma only", "Infected wax"], 1, "Despite its name, cholesteatoma is misplaced keratinising skin (not tumour, not cholesterol) accumulating keratin that expands and erodes bone. Cholesterol granuloma is a separate bloody middle ear lesion.", ["Incorrect. It is benign misplaced epithelium, not malignancy.", "Correct. Skin in middle ear trapping keratin.", "Incorrect. Cholesterol granuloma differs histologically.", "Incorrect. Wax sits in canal and removes easily."], "Not cancer, not cholesterol: trapped skin keratin."),
  mcq("bk2-ent-023", "Definitive treatment of cholesteatoma is what?", ["Long term ear drops", "Surgical mastoidectomy removal", "Systemic antibiotics alone", "Syringing"], 1, "Only surgery excises cholesteatoma matrix and diseased mastoid, creating safe ear; drops and antibiotics merely reduce discharge temporarily. Delay risks intracranial spread.", ["Incorrect. Drops temporise discharge only.", "Correct. Mastoid surgery is definitive.", "Incorrect. Antibiotics cannot remove keratin matrix.", "Incorrect. Syringing spreads infection through perforation."], "Keratin sacs come out surgically or not at all."),
  mcq("bk2-ent-024", "Chronic ear discharge with new vertigo suggests which complication?", ["Wax impaction", "Labyrinthine fistula or labyrinthitis", "Glue ear formation", "Otosclerosis"], 1, "Cholesteatoma eroding the lateral semicircular canal fistulises the labyrinth, causing pressure induced vertigo, or infects it as labyrinthitis with deafness. This needs urgent ENT care.", ["Incorrect. Wax causes canal blockage, not fistula vertigo.", "Correct. Erosion into labyrinth causes vertigo.", "Incorrect. Effusion deafens without acute vertigo.", "Incorrect. Otosclerosis fixes stapes without discharge."], "Chronic ear plus spinning: labyrinth breached."),
  mcq("bk2-ent-025", "Safe CSOM perforation is characteristically located where?", ["Attic (pars flaccida)", "Central pars tensa", "Marginal posterior", "Drum intact"], 1, "Central pars tensa perforations with mucosal disease define safe tubotympanic CSOM. Attic (flaccida) and marginal perforations signal cholesteatoma risk and unsafe disease.", ["Incorrect. Attic perforation is unsafe cholesteatoma site.", "Correct. Central pars tensa means safe disease.", "Incorrect. Marginal perforations are unsafe.", "Incorrect. Intact drum excludes discharging CSOM."], "Centre is safe; edges and attic are dangerous."),
  mcq("bk2-ent-026", "Most acquired cholesteatomas arise by which mechanism?", ["Blood borne spread", "Retraction pocket from Eustachian dysfunction trapping keratin", "Viral transformation", "Traumatic implantation always"], 1, "Chronic negative middle ear pressure retracts the attic drum into a self trapping pocket whose keratin cannot clear, expanding as cholesteatoma. Other routes (migration, metaplasia) are less common.", ["Incorrect. Cholesteatoma grows locally, not haematogenous.", "Correct. Retraction pocket trapping keratin.", "Incorrect. No viral oncogenesis involved.", "Incorrect. Implantation after trauma is rare minority route."], "Sucked in attic pocket that cannot self clean."),
  mcq("bk2-ent-027", "Canal wall down mastoidectomy trades anatomy for what advantage?", ["No follow up needed", "Exteriorised disease visible for surveillance and cleaning", "Better hearing always", "No cavity care"], 1, "Opening mastoid into canal exteriorises residual disease for direct inspection and cleaning, reducing hidden recurrence, at cost of lifelong cavity maintenance and water precautions.", ["Incorrect. Cavities need regular lifelong care.", "Correct. Visible exteriorised cavity aids surveillance.", "Incorrect. Hearing often worse than wall up reconstructions.", "Incorrect. Cavity care is the main burden."], "Wall down: watch it easily, clean it forever."),
  mcq("bk2-ent-028", "Congenital cholesteatoma is recognised by what presentation?", ["Attic perforation in adult", "White mass behind intact drum in a child", "Foul discharge from canal", "Post traumatic perforation"], 1, "Embryonic epithelial rests grow as white pearls behind intact drums in children without infection history, found on routine otoscopy. Acquired disease needs perforation or retraction history.", ["Incorrect. That is acquired attic disease.", "Correct. Intact drum white mass in child.", "Incorrect. Discharge implies acquired infected disease.", "Incorrect. Trauma gives perforation, not congenital pearl."], "Quiet white pearl behind whole drum in child: congenital."),
  mcq("bk2-ent-029", "A dry central perforation with conductive loss is best offered what?", ["Mastoidectomy", "Myringoplasty (tympanoplasty) after dry period", "Hearing aid refusal", "Chronic drops"], 1, "Dry safe perforations are closed by myringoplasty grafting, restoring drum barrier and often hearing. Mastoidectomy is for cholesteatoma or refractory mastoid disease; drops treat only wet flares.", ["Incorrect. No mastoid disease to remove in dry safe ear.", "Correct. Graft the dry central hole.", "Incorrect. Aids help but surgery offered first where suitable.", "Incorrect. Drops do not close perforations."], "Dry central hole: graft it closed."),
  mcq("bk2-ent-030", "Imaging best detecting residual cholesteatoma after surgery is what?", ["Plain mastoid X ray", "Diffusion weighted MRI", "CT alone always", "Ultrasound"], 1, "Non echo planar diffusion MRI highlights keratin pearls brightly, detecting residual or recurrent cholesteatoma without second look surgery. CT shows bone anatomy but cannot distinguish pearl from scar reliably.", ["Incorrect. Plain films lack sensitivity.", "Correct. Diffusion MRI finds keratin pearls.", "Incorrect. CT cannot separate pearl from granulation.", "Incorrect. Ultrasound cannot image mastoid bone disease."], "After surgery, diffusion MRI hunts leftover pearls.")]);

add("ent-om-complications", "Complications of otitis media", "complications_of_otitis_media", "Complications of Otitis Media",
 ["Mastoiditis", "Brain abscess otogenic", "Lateral sinus thrombosis", "Gradenigo syndrome"],
 [step("Middle ear infection spreads beyond its box by direct bone erosion, thrombophlebitic veins or preformed pathways into mastoid, labyrinth, meninges, brain and sigmoid sinus. Antibiotics reduced but never abolished these complications, and chronic cholesteatoma erodes silently toward them. Any ear infection with headache, fever persistence, swelling or neurology is complicated until assessed.", "Ear infection escaping its box threatens mastoid, brain and venous sinuses. Headache, swelling or neurology with ear disease means complication until checked."),
  step("**Acute mastoiditis** follows otitis media when pus fills mastoid air cells and erodes their septa: postauricular swelling pushes the pinna forward and down, with fever and mastoid tenderness. Subperiosteal abscess fluctuates behind the ear; Bezold abscess tracks into the neck. CT confirms coalescent mastoiditis; drainage plus mastoid surgery treats abscess or intracranial extension.", "Mastoiditis swells behind the ear pushing pinna out. Abscess or brain spread needs drainage and mastoid surgery."),
  step("Intracranial spread causes **meningitis** (commonest intracranial complication), extradural and subdural empyema, and temporal lobe or cerebellar **brain abscess** classically with headache, fever, seizures or focal signs and a swinging course. Otogenic abscesses often grow mixed anaerobes and gram negatives. Neurosurgical drainage plus ear surgery and prolonged antibiotics are combined.", "Ear brain abscesses hide in temporal lobe and cerebellum with headache and seizures. Drain brain and ear together with long antibiotics."),
  step("**Lateral (sigmoid) sinus thrombophlebitis** seeds picket fence swinging fevers with rigors as infected clot showers the bloodstream, plus papilloedema from venous hypertension. Gradenigo syndrome combines otorrhoea, retro-orbital pain (trigeminal) and abducens palsy from petrous apex inflammation. Labyrinthitis and facial palsy complete the classic complication catalogue tested repeatedly.", "Swinging rigors with ear disease mean infected sinus clot. Eye pain plus double vision plus discharging ear means Gradenigo at the petrous tip.", tbl(["Complication", "Site", "Signature clue"], [["Mastoiditis", "Mastoid air cells", "Postauricular swelling, pinna displaced"], ["Brain abscess", "Temporal lobe or cerebellum", "Headache, seizure, focal signs"], ["Lateral sinus thrombosis", "Sigmoid sinus", "Picket fence rigors, papilloedema"], ["Gradenigo", "Petrous apex", "Otorrhoea, eye pain, abducens palsy"]])),
  step("Facial nerve traverses the middle ear and mastoid, so infection or cholesteatoma paralyses it; labyrinthine fistula gives vertigo on pressure. Management principles never change: image urgently, start broad antibiotics per protocol, involve ENT and neurosurgery, and operate the ear source once the patient is stabilised. Lumbar puncture waits for imaging when abscess or raised pressure is possible.", "Facial palsy or pressure vertigo with ear disease signals nerve or labyrinth breach. Scan first, puncture later when pressure threatens.")],
 ["Mastoiditis: postauricular swelling displacing pinna", "Commonest intracranial complication of otitis media is meningitis", "Picket fence fever means lateral sinus thrombophlebitis", "Gradenigo triad: otorrhoea, retro-orbital pain, abducens palsy"],
 "Infection breaches thin tegmen, sinus plates and labyrinthine windows directly or via thrombophlebitic emissary veins, seeding meninges, brain parenchyma and venous sinuses from the infected mastoid reservoir.",
 ["Coalescent mastoiditis versus postauricular lymphadenitis", "Otogenic versus rhinogenic brain abscess site clues", "Labyrinthitis (deaf vertigo) versus benign positional vertigo"],
 ["CT temporal bone with contrast; MRI brain when intracranial signs", "Blood cultures during rigor; audiometry", "Lumbar puncture only after imaging clearance"],
 [mcq("bk2-ent-031", "Child with otitis media now has postauricular swelling pushing the pinna forward and fever. Diagnosis?", ["Otitis externa", "Acute mastoiditis", "Wax granuloma", "Perichondritis"], 1, "Pus coalescing in mastoid air cells with subperiosteal swelling displaces the pinna in mastoiditis, the commonest complication of acute otitis media needing imaging and surgical assessment.", ["Incorrect. Canal disease does not displace pinna from behind.", "Correct. Postauricular swelling with pinna displacement is mastoiditis.", "Incorrect. Wax stays in canal without fever swelling.", "Incorrect. Perichondritis inflames pinna itself, sparing mastoid."], "Swelling behind ear pushing pinna out: mastoiditis."),
  mcq("bk2-ent-032", "Commonest intracranial complication of otitis media is which?", ["Brain abscess", "Meningitis", "Sinus thrombosis", "Subdural empyema"], 1, "Meningitis is the most frequent intracranial complication of otitis media, ahead of abscess and sinus thrombosis. Any ear infection with meningism needs urgent antibiotics and imaging guided puncture decisions.", ["Incorrect. Abscess is feared but less common than meningitis.", "Correct. Meningitis is commonest intracranially.", "Incorrect. Sinus thrombosis is rarer still.", "Incorrect. Empyema is uncommon."], "Ear to meninges is the commonest deep escape."),
  mcq("bk2-ent-033", "Swinging picket fence fevers with rigors in chronic ear disease suggest what?", ["Labyrinthitis", "Lateral sinus thrombophlebitis", "Mastoiditis simple", "Facial palsy"], 1, "Infected sigmoid sinus clot intermittently showers bacteria causing hectic picket fence rigors, with papilloedema from venous obstruction. Blood cultures taken during rigor grow the organism.", ["Incorrect. Labyrinthitis causes vertigo and deafness.", "Correct. Hectic rigors mean infected sinus clot.", "Incorrect. Simple mastoiditis gives steady local fever.", "Incorrect. Palsy is motor, not septic pattern."], "Rigors like a picket fence: sinus clot seeding blood."),
  mcq("bk2-ent-034", "Otorrhoea, retro-orbital pain and abducens palsy together form which syndrome?", ["Ramsay Hunt", "Gradenigo syndrome", "Tolosa Hunt", "Frey syndrome"], 1, "Petrous apicitis inflames structures at the petrous tip: trigeminal pain behind the eye plus abducens palsy with ear discharge is Gradenigo syndrome, a mastoiditis complication variant.", ["Incorrect. Ramsay Hunt is facial palsy with vesicles.", "Correct. Gradenigo triad at petrous apex.", "Incorrect. Tolosa Hunt is painful ophthalmoplegia without ear disease.", "Incorrect. Frey is gustatory sweating after parotid surgery."], "Ear discharge plus eye pain plus lateral gaze palsy: Gradenigo."),
  mcq("bk2-ent-035", "Otogenic brain abscess most characteristically lodges where?", ["Frontal lobe only", "Temporal lobe and cerebellum", "Occipital lobe", "Brainstem"], 1, "Contiguous spread through tegmen reaches temporal lobe, and via Trautmann triangle to cerebellum, so otogenic abscesses occupy these two sites. Frontal abscesses instead follow sinusitis.", ["Incorrect. Frontal abscess is classic for sinus source.", "Correct. Temporal lobe and cerebellum for ear source.", "Incorrect. Occipital lesions suggest haematogenous spread.", "Incorrect. Brainstem abscess is rare and usually blood borne."], "Ear abscess: temporal lobe or cerebellum."),
  mcq("bk2-ent-036", "Facial palsy appearing with acute otitis media most often needs what principle?", ["Ignore until infection clears", "Urgent ENT assessment; decompression considered with mastoid surgery", "Steroids alone for months", "Facial exercises only"], 1, "The facial canal often dehisces in middle ear, so infection inflames or compresses the nerve. Urgent specialist care with antibiotics and possible surgical decompression or mastoid clearance protects recovery.", ["Incorrect. Delay worsens nerve outcome.", "Correct. Urgent ENT care and source surgery assessment.", "Incorrect. Steroids alone ignore infected source.", "Incorrect. Exercises do not treat compression."], "Weak face with infected ear: urgent source control."),
  mcq("bk2-ent-037", "Bezold abscess is mastoid pus tracking where?", ["Into the cheek", "Deep into neck along sternomastoid", "Into the orbit", "Into the palate"], 1, "Pus perforating the medial mastoid tip tracks deep to sternomastoid into the neck as Bezold abscess, presenting as neck swelling with torticollis in mastoiditis. It needs drainage with mastoid surgery.", ["Incorrect. Cheek swelling is dental or parotid source.", "Correct. Neck tracking from mastoid tip is Bezold.", "Incorrect. Orbit complications come from ethmoid sinuses.", "Incorrect. Palatal swelling is dental or tonsillar."], "Mastoid tip pus in neck equals Bezold abscess."),
  mcq("bk2-ent-038", "Vertigo induced by pressure on the tragus in chronic ear disease indicates what?", ["Benign positional vertigo", "Labyrinthine fistula (positive fistula sign)", "Meniere disease", "Acoustic neuroma"], 1, "Cholesteatoma eroding the lateral canal lets pressure transmit to labyrinth, causing vertigo and nystagmus on tragus pressure: positive fistula sign needing urgent surgery planning without repeated pressure testing.", ["Incorrect. BPPV follows head position, not tragus pressure, without ear disease.", "Correct. Pressure vertigo means labyrinth fistula.", "Incorrect. Meniere has episodic vertigo with fluctuating hearing, no fistula.", "Incorrect. Neuroma deafens slowly without pressure fistula signs."], "Press the ear, world spins: fistula present."),
  mcq("bk2-ent-039", "Before lumbar puncture in suspected otogenic brain abscess, what must happen?", ["Start oral antibiotics", "Brain imaging to exclude mass effect", "Mastoid X ray", "Audiogram"], 1, "Puncturing with abscess or raised intracranial pressure risks coning, so CT or MRI precedes lumbar puncture whenever focal signs, seizures or papilloedema exist. Cultures and antibiotics should not wait meanwhile per protocol.", ["Incorrect. Route matters less than herniation safety sequence.", "Correct. Image first when abscess possible.", "Incorrect. Mastoid films do not clear puncture safety.", "Incorrect. Hearing tests never gate puncture."], "Possible abscess: scan before needle."),
  mcq("bk2-ent-040", "Labyrinthitis complicating ear infection typically causes what hearing pattern?", ["Conductive loss only", "Sensorineural loss with severe vertigo", "Mixed loss without vertigo", "Normal hearing with tinnitus only"], 1, "Infection or toxins entering inner ear destroy cochlear and vestibular function together: profound sensorineural deafness with violent vertigo, nausea and nystagmus. Serous forms may partly recover; suppurative usually not.", ["Incorrect. Inner ear injury is sensorineural, not conductive.", "Correct. Sensorineural deafness plus severe vertigo.", "Incorrect. Vertigo is defining, not absent.", "Incorrect. Hearing loss is major, not spared."], "Deaf plus spinning after ear infection: labyrinth inflamed.")]);

add("ent-otosclerosis", "Otosclerosis and conductive deafness", "otosclerosis_and_conductive_deafness", "Otosclerosis and Conductive Deafness",
 ["Otosclerosis", "Stapedectomy", "Schwartze sign", "Conductive hearing loss"],
 [step("Conductive deafness arises when sound fails through canal, drum or ossicles: wax, perforation, effusion, ossicular erosion or fixation. Air conduction falls while bone conduction stays normal, creating an air bone gap on audiometry, with Rinne negative and Weber lateralising to the worse ear on tuning fork tests. The pattern, not just severity, directs the search.", "Blocked sound path deafens air conduction while bone stays normal. Tuning forks point to the bad ear in conductive loss."),
  step("**Otosclerosis** is abnormal bone remodelling of the otic capsule fixing the stapes footplate, causing slowly progressive conductive loss in young adults, often women, worsening in pregnancy, with family history and normal drums. Tinnitus accompanies, and speech discrimination stays good. Bilateral disease is usual over time.", "Otosclerosis glues the stapes in young adults, often women, slowly deafening with normal drums and family pattern."),
  step("Audiometry shows air bone gap with a characteristic dip in bone conduction at 2000 Hz (Carhart notch), an artefact of stapes fixation rather than cochlear damage. Tympanometry stiffens (As type) and stapedial reflex vanishes. Schwartze sign, a pink blush behind the drum from vascular active bone, appears in a minority. CT can show lucency at the fissula ante fenestram in active disease.", "Carhart notch at 2 kHz with stiff drum tracing marks stapes fixation. Pink blush behind drum is the uncommon Schwartze sign."),
  step("Management offers amplification or **stapes surgery** (stapedotomy with piston prosthesis) restoring the gap in most operated ears, with small risks of sensorineural loss, vertigo and taste change via chorda tympani. Sodium fluoride historically aimed to slow active cochlear disease but is not standard cure. Cochlear otosclerosis adds sensorineural loss needing aids or implants when severe.", "Hearing aids or stapes piston surgery close the gap. Surgery risks inner ear, so counselling matters."),
  step("Other fixation and discontinuity causes matter: tympanosclerosis plaques after chronic infection stiffen drum and ossicles, traumatic incus dislocation interrupts the chain after head injury (often with haemotympanum), and congenital fixation presents from childhood without progression pattern of otosclerosis. Surgical exploration with ossiculoplasty addresses selected mechanical defects.", "Scarred stiff drums, dislocated incus after trauma and congenital fixation mimic otosclerosis. History separates them.")],
 ["Young adult progressive conductive loss, normal drum: otosclerosis", "Carhart notch is bone dip at 2000 Hz in otosclerosis", "Weber lateralises to affected ear in conductive loss", "Stapedotomy piston is definitive mechanical correction"],
 "Spongy vascular bone replaces dense otic capsule and fixes the stapes footplate at the oval window, blocking piston motion into the cochlea while inner ear initially remains normal.",
 ["Otosclerosis versus ossicular discontinuity (hypermobile tympanogram)", "Conductive versus sensorineural loss by forks and audiogram", "Tympanosclerosis versus otosclerosis history (infection versus family)"],
 ["Pure tone audiometry with bone conduction", "Tympanometry and acoustic reflexes", "High resolution CT temporal bone in selected cases"],
 [mcq("bk2-ent-041", "In unilateral conductive loss, Weber test lateralises where?", ["To better ear", "To affected ear", "Midline always", "Away from affected ear"], 1, "Bone conducted sound seems louder in the conductively deaf ear because ambient masking is reduced and bone energy escapes less, so Weber points to the worse ear in conductive loss and to better ear in sensorineural loss.", ["Incorrect. Better ear lateralisation means sensorineural loss opposite.", "Correct. Weber goes to the conductively deaf ear.", "Incorrect. Midline suggests symmetry or normal.", "Incorrect. Away would be sensorineural pattern."], "Conductive: Weber visits the bad ear."),
  mcq("bk2-ent-042", "Carhart notch in otosclerosis is best described as what?", ["Air conduction dip at 4 kHz", "Bone conduction dip at 2000 Hz", "Flat tympanogram", "Absent drum"], 1, "Stapes fixation artefactually depresses bone conduction at 2000 Hz, producing Carhart notch that disappears after successful surgery, proving it mechanical not cochlear. Noise notch instead hits air conduction at 4 kHz.", ["Incorrect. Four kilohertz air notch means noise trauma.", "Correct. Bone dip at 2 kHz is Carhart notch.", "Incorrect. Tympanometry stiffness is separate measure.", "Incorrect. Drum is normal in otosclerosis."], "Two kilohertz bone dip equals Carhart."),
  mcq("bk2-ent-043", "Young woman with progressive bilateral conductive loss, normal drums and affected mother most likely has what?", ["Glue ear", "Otosclerosis", "Cholesteatoma", "Presbycusis"], 1, "Autosomal dominant otosclerosis fixes stapes in young adults (female predominance, pregnancy worsening) with pristine drums. Glue ear shows effusion, cholesteatoma discharge, presbycusis sensorineural old age loss.", ["Incorrect. Effusion would dull the drum.", "Correct. Familial stapes fixation is otosclerosis.", "Incorrect. Cholesteatoma discharges and perforates.", "Incorrect. Presbycusis is sensorineural ageing loss."], "Normal drum, young adult, family deafness: otosclerosis."),
  mcq("bk2-ent-044", "Definitive surgical correction for otosclerosis is what?", ["Myringoplasty", "Stapedotomy with piston prosthesis", "Mastoidectomy", "Grommet insertion"], 1, "Small fenestra stapedotomy bypasses fixed footplate with a piston between incus and oval window, closing air bone gap in most cases. Drum and mastoid operations address different diseases.", ["Incorrect. Myringoplasty closes perforations.", "Correct. Piston prosthesis bypasses fixed stapes.", "Incorrect. Mastoidectomy clears infected mastoid.", "Incorrect. Grommets ventilate glue ear."], "Fixed stapes gets a piston bypass."),
  mcq("bk2-ent-045", "Schwartze sign in otitis media examination means what?", ["Blue drum from blood", "Pink blush behind drum from active otosclerotic bone", "White cholesteatoma pearl", "Black fungal debris"], 1, "Vascular spongy bone shining through the drum gives a flamingo pink Schwartze sign in active otosclerosis, present only in minority. Blue drum suggests haemotympanum or cholesterol granuloma.", ["Incorrect. Blue drum is blood or granuloma.", "Correct. Pink blush means active otosclerotic foci.", "Incorrect. White pearl is cholesteatoma.", "Incorrect. Black debris is fungal canal disease."], "Pink glow behind drum: active otosclerosis."),
  mcq("bk2-ent-046", "Rinne test in conductive loss of the tested ear shows what?", ["Air louder than bone (positive)", "Bone louder than air (negative)", "Equal always", "No response either"], 1, "When conduction fails, bone conduction bypassing the block exceeds air conduction in that ear: Rinne negative, the classic conductive pattern. Normal and sensorineural ears keep air louder (positive).", ["Incorrect. Positive Rinne is normal or sensorineural.", "Correct. Negative Rinne (bone over air) means conductive.", "Incorrect. Equality is equivocal borderline.", "Incorrect. Profound sensorineural loss gives false negative needing masking care."], "Bone beats air equals conductive loss."),
  mcq("bk2-ent-047", "Otosclerosis typically worsens during which physiological state?", ["Puberty in males", "Pregnancy", "Menopause only", "Childhood"], 1, "Hormonal changes of pregnancy classically accelerate otosclerosis progression, one reason women present more. Onset is young adult, not childhood, and progression is slow over years.", ["Incorrect. Male puberty is not the accelerator.", "Correct. Pregnancy worsens otosclerosis.", "Incorrect. Menopause is not the classic trigger.", "Incorrect. Childhood fixation suggests congenital causes."], "Pregnancy pours fuel on otosclerosis."),
  mcq("bk2-ent-048", "Tympanometry in stapes fixation typically shows which curve?", ["Flat B", "Shallow stiff As curve", "Deep Ad curve", "Normal A always"], 1, "Fixed ossicular chain stiffens the system giving shallow As tympanogram with preserved peak position but reduced compliance. Flat B is effusion; deep Ad is discontinuity or flaccid drum.", ["Incorrect. Flat B means fluid or perforation patterns.", "Correct. Shallow stiff As curve in fixation.", "Incorrect. Deep Ad means hypermobile system.", "Incorrect. Curve is measurably shallow, not normal."], "Stiff shallow tracing: fixed chain."),
  mcq("bk2-ent-049", "Traumatic ossicular discontinuity most commonly dislocates which ossicle joint?", ["Stapes footplate", "Incudostapedial joint", "Malleus head fixation", "Round window"], 1, "The incus, precariously suspended, dislocates at incudostapedial joint (or its body) after head trauma, causing immediate conductive gap with hypermobile tympanogram. Reconstruction uses ossiculoplasty prostheses.", ["Incorrect. Footplate fracture is rarer and risks inner ear.", "Correct. Incudostapedial dislocation is commonest.", "Incorrect. Malleus fixation is congenital or tympanosclerotic.", "Incorrect. Round window injury causes sensorineural patterns."], "Trauma knocks the loosely hung incus loose."),
  mcq("bk2-ent-050", "Cochlear otosclerosis differs by adding which loss component?", ["Conductive only", "Sensorineural loss from capsular invasion", "Central deafness", "Functional loss"], 1, "Foci invading cochlear capsule injure inner ear adding sensorineural (mixed) loss, limiting surgical gain and pushing toward amplification or implantation in severe disease.", ["Incorrect. Pure conductive is fenestral disease only.", "Correct. Cochlear invasion adds sensorineural loss.", "Incorrect. Lesion is capsular, not brain pathways.", "Incorrect. Functional loss shows inconsistent audiometry."], "When otosclerosis invades cochlea, loss turns mixed.")]);

add("ent-snhl-inner-ear", "Sensorineural hearing loss and inner ear disorders", "sensorineural_loss_and_inner_ear", "Sensorineural Hearing Loss and Inner Ear Disorders",
 ["Meniere disease", "Acoustic neuroma", "Sudden sensorineural loss", "Presbycusis", "Labyrinthitis"],
 [step("**Sensorineural loss** localises to cochlea (sensory) or auditory nerve (neural or retrocochlear): both air and bone conduction fall together without gap, Weber lateralises to the better ear and Rinne stays positive. Speech discrimination suffers, recruitment and tinnitus feature, and tuning forks can mislead in dead ears without masking. Audiometry plus speech scores grade and lateralise disease.", "Inner ear or nerve loss drops air and bone together. Weber flees to the good ear. Speech clarity suffers beyond mere loudness."),
  step("**Meniere disease** gives episodic vertigo lasting tens of minutes to hours with fluctuating low frequency sensorineural loss, tinnitus and aural fullness in one ear, from endolymphatic hydrops. Attacks cluster then burn out leaving progressive loss. Lifestyle, betahistine or diuretics per local practice, intratympanic therapy and surgery escalate for disabling vertigo, while bilateral disease limits ablative options.", "Meniere attacks spin for minutes to hours with roaring tinnitus, fullness and fluctuating deafness in one ear."),
  step("**Sudden sensorineural loss** (30 dB or more over three frequencies within days) is an otologic emergency: most is idiopathic or viral, but stroke and neuroma hide among cases, so urgent audiometry, early steroids per protocol timing, and MRI internal auditory meatus follow. Delayed treatment worsens recovery odds. Bilateral sudden loss suggests systemic, drug or autoimmune causes.", "Sudden deafness is an emergency: confirm quickly, treat early, scan the nerve pathway. Delay costs hearing."),
  step("**Vestibular schwannoma (acoustic neuroma)** grows slowly from the vestibular nerve in the cerebellopontine angle causing unilateral progressive sensorineural loss, tinnitus and imbalance, later trigeminal and facial signs when large. Bilateral tumours define neurofibromatosis type 2. MRI gadolinium of internal meatus diagnoses; observation, radiosurgery or microsurgery balance growth against hearing and facial function.", "Slow one sided deafness with tinnitus needs neuroma excluded by MRI. Bilateral tumours mean NF2."),
  step("Other inner ear diseases fill exams: **presbycusis** symmetric high frequency ageing loss; noise trauma notches at 4 kHz; ototoxic aminoglycosides and cisplatin kill outer hair cells base first (high frequencies) needing monitoring; perilymph fistula and superior canal dehiscence cause pressure or sound induced vertigo (Tullio); autoimmune inner ear disease progresses bilaterally over weeks and answers steroids.", "Ageing and noise take high tones first. Ototoxic drugs need hearing monitoring. Sound induced spinning suggests canal dehiscence.", tbl(["Disorder", "Vertigo pattern", "Hearing pattern"], [["Meniere disease", "Episodic 20 min to hours", "Fluctuating low frequency SNHL"], ["BPPV", "Seconds on rolling over", "Normal hearing"], ["Labyrinthitis", "Days severe after ear infection", "SNHL with deaf ear"], ["Canal dehiscence", "Sound or pressure induced brief", "Conductive like gap with good bone"]]))],
 ["Meniere tetrad: episodic vertigo, fluctuating loss, tinnitus, fullness", "Sudden SNHL is emergency needing early steroids and MRI", "Unilateral SNHL mandates neuroma exclusion imaging", "Aminoglycoside ototoxicity hits high frequencies first"],
 "Endolymph volume expansion distends cochlear and vestibular compartments until membranes rupture mixing fluids and triggering attacks; hair cell death from ageing, noise, drugs or ischaemia removes transduction while nerve tumours compress conduction.",
 ["Meniere versus BPPV by attack duration and hearing symptoms", "Cochlear versus retrocochlear loss (reflex decay, MRI)", "Ototoxic versus noise loss history patterns"],
 ["Pure tone and speech audiometry urgently for sudden loss", "MRI internal auditory meatus with gadolinium for unilateral loss", "Vestibular testing and high resolution CT for dehiscence"],
 [mcq("bk2-ent-051", "Episodic vertigo for 2 hours with roaring tinnitus, fullness and fluctuating one ear deafness indicates what?", ["BPPV", "Meniere disease", "Labyrinthitis", "Perilymph fistula only"], 1, "Meniere disease from endolymphatic hydrops produces 20 minute to 12 hour vertigo attacks with fluctuating low frequency sensorineural loss, tinnitus and fullness. BPPV lasts seconds without hearing change.", ["Incorrect. BPPV spins for seconds on rolling, hearing normal.", "Correct. Hours of vertigo with fluctuating ear symptoms is Meniere.", "Incorrect. Labyrinthitis follows infection with constant days of vertigo and fixed loss.", "Incorrect. Fistula vertigo is pressure triggered and brief."], "Minutes to hours spinning plus ear fullness equals Meniere."),
  mcq("bk2-ent-052", "Sudden 40 dB sensorineural loss over 2 days requires which urgent pathway?", ["Reassure and review in 6 months", "Urgent audiometry, early steroid consideration and MRI meatus", "Ear syringing", "Hearing aid fitting next year"], 1, "Sudden sensorineural loss is an emergency: prompt steroids within the early window improve recovery chances, and MRI excludes vestibular schwannoma or stroke. Wax would be conductive and visible.", ["Incorrect. Delay forfeits the treatment window.", "Correct. Urgent confirmation, steroids and MRI.", "Incorrect. Syringing treats canal wax, not cochlear loss.", "Incorrect. Aid fitting waits for recovery plateau."], "Sudden deaf ear: days matter, scan and treat."),
  mcq("bk2-ent-053", "Slowly progressive unilateral sensorineural loss with tinnitus and poor speech discrimination needs exclusion of what?", ["Otosclerosis", "Vestibular schwannoma", "Glue ear", "Wax"], 1, "Retrocochlear tumours cause asymmetric sensorineural loss with disproportionately poor discrimination; gadolinium MRI of internal auditory meatus is mandatory. Conductive causes show air bone gaps instead.", ["Incorrect. Otosclerosis is conductive with good discrimination.", "Correct. Exclude vestibular schwannoma by MRI.", "Incorrect. Glue ear is conductive effusion.", "Incorrect. Wax blocks canal visibly."], "One sided neural deafness: image the meatus."),
  mcq("bk2-ent-054", "Bilateral vestibular schwannomas define which condition?", ["Neurofibromatosis type 1", "Neurofibromatosis type 2", "Von Hippel Lindau", "Tuberous sclerosis"], 1, "Bilateral vestibular schwannomas are diagnostic of NF2 (chromosome 22 merlin loss), with meningiomas and ependymomas. NF1 gives neurofibromas and cafe au lait spots instead.", ["Incorrect. NF1 is peripheral neurofibromas and skin signs.", "Correct. Bilateral schwannomas mean NF2.", "Incorrect. VHL gives haemangioblastomas and renal tumours.", "Incorrect. Tuberous sclerosis gives cortical tubers and angiofibromas."], "Two acoustic tumours equals NF2."),
  mcq("bk2-ent-055", "Noise induced hearing loss classically notches the audiogram where?", ["500 Hz", "4000 Hz", "250 Hz bone only", "8000 Hz sparing"], 1, "Acoustic trauma injures basal hair cells tuned near 4 kHz (3 to 6 kHz range) producing the classic audiometric notch with later spread. Low frequencies survive until late damage.", ["Incorrect. Low frequencies are spared early.", "Correct. Notch at 4 kHz is noise signature.", "Incorrect. Bone and air fall together sensorineurally.", "Incorrect. Highest tested tones also suffer with progression."], "Factory and gunfire carve the 4 kHz notch."),
  mcq("bk2-ent-056", "Aminoglycoside ototoxicity first damages hearing in which range and needs what monitoring?", ["Low frequencies; none", "High frequencies; serial audiometry", "Speech frequencies only; visual checks", "Bone conduction only"], 1, "Ototoxins destroy basal outer hair cells first, so high frequency loss precedes speech range symptoms; baseline and serial high frequency audiometry (plus vestibular vigilance) monitor therapy.", ["Incorrect. Low tones fall late, and monitoring is essential.", "Correct. High frequencies first with serial audiograms.", "Incorrect. Speech range loss is late presentation.", "Incorrect. Both conduction routes reflect cochlea."], "Ototoxins eat from the high tone base upward: monitor."),
  mcq("bk2-ent-057", "Vertigo provoked by loud sounds (Tullio phenomenon) suggests which lesion?", ["BPPV crystals", "Superior semicircular canal dehiscence", "Meniere hydrops", "Otosclerosis"], 1, "A bony dehiscence creates a third window so sound and pressure move endolymph causing brief vertigo and autophony, confirmed on fine cut CT and vestibular evoked potentials. Plugging surgery helps severe cases.", ["Incorrect. Crystals trigger position, not sound.", "Correct. Sound induced vertigo means canal dehiscence.", "Incorrect. Meniere attacks are spontaneous and prolonged.", "Incorrect. Otosclerosis deafens conductively without sound vertigo."], "Loud sound makes world tilt: third window leak."),
  mcq("bk2-ent-058", "Presbycusis audiogram characteristically shows what?", ["Unilateral flat loss", "Bilateral symmetric high frequency sensorineural loss", "Conductive gap", "Low frequency fluctuating loss"], 1, "Ageing cochlear loss is bilateral, symmetric and high frequency sloping, impairing consonant discrimination especially in noise. Unilateral or fluctuating patterns demand other diagnoses.", ["Incorrect. Unilateral loss needs retrocochlear exclusion.", "Correct. Symmetric high frequency slope of ageing.", "Incorrect. No air bone gap in cochlear ageing.", "Incorrect. Fluctuating low loss is Meniere pattern."], "Old ears lose high tones on both sides together."),
  mcq("bk2-ent-059", "BPPV is distinguished from Meniere primarily how?", ["Vertigo seconds triggered by rolling, normal hearing", "Vertigo days with deafness", "Tinnitus and fullness", "Fever present"], 0, "Benign paroxysmal positional vertigo gives seconds long spins on rolling or looking up, positive Dix Hallpike, treated by Epley repositioning, with normal hearing. Meniere attacks last far longer with ear symptoms.", ["Correct. Brief positional spins, normal hearing: BPPV.", "Incorrect. Days of vertigo with deafness is labyrinthitis.", "Incorrect. Those are Meniere auditory features.", "Incorrect. Fever points to infectious labyrinth disease."], "Seconds on rolling equals crystals, hours with fullness equals Meniere."),
  mcq("bk2-ent-060", "Autoimmune inner ear disease typically progresses how and responds to what?", ["One ear over decades; surgery", "Bilateral over weeks to months; corticosteroids", "Sudden one ear; antibiotics", "Childhood congenital; aids only"], 1, "Immune mediated cochlear injury progresses bilaterally over weeks to months (too slow for sudden loss, too fast for ageing) and often stabilises with corticosteroids, needing rheumatologic co care.", ["Incorrect. Decades unilateral suggests tumour pathway.", "Correct. Bilateral subacute progression answering steroids.", "Incorrect. Antibiotics treat infectious labyrinthitis.", "Incorrect. Congenital loss is non progressive pattern."], "Both ears worsening over weeks: think immune, try steroids.")]);

add("ent-facial-nerve", "Facial nerve and its disorders", "facial_nerve_disorders", "Facial Nerve and Its Disorders",
 ["Bell palsy", "Facial nerve palsy", "House Brackmann", "Ramsay Hunt"],
 [step("The **facial nerve** exits the pons, traverses the internal meatus and temporal bone (labyrinthine, tympanic and mastoid segments), gives greater petrosal, stapedial and chorda tympani branches, then exits the stylomastoid foramen to supply facial muscles, stapedius and taste to anterior tongue. Its long bony canal explains vulnerability to ear disease and temporal fractures.", "Facial nerve winds through ear bone supplying face movement, stapedius and front tongue taste. Ear disease and fractures threaten it."),
  step("**Bell palsy** is acute idiopathic lower motor neuron facial paralysis (forehead included) reaching peak within days, likely herpetic inflammation swelling the nerve in its tight labyrinthine segment. Early corticosteroids within 72 hours improve complete recovery; antivirals add debated benefit, and eye protection (lubrication, taping) prevents corneal damage when closure fails. Most recover well.", "Bell palsy weakens the whole face including forehead, peaking fast. Early steroids help; protect the open eye."),
  step("Lower versus upper motor neuron signs separate urgently: forehead sparing means central (stroke) because forehead receives bilateral cortical input, while forehead involvement means peripheral nerve lesion. Ramsay Hunt adds vesicles and worse prognosis; Lyme, sarcoid, parotid tumours and otitis cause secondary palsies needing cause treatment, not Bell label.", "Forehead spared means brain lesion; forehead weak means nerve lesion. Blisters, lumps or ear infection mean not simple Bell palsy."),
  step("Temporal bone fractures paralyse by segment: longitudinal fractures (commoner) tear along the bone often with conductive loss and CSF otorrhoea, while transverse fractures cross the labyrinth causing sensorineural loss, vertigo and higher facial palsy rates. Delayed palsy (oedema) recovers better than immediate (transection). Surgical decompression or repair is selected by electrophysiology and imaging in specialist care.", "Transverse temporal fractures deafen sensorineurally and paralyse more; longitudinal cause conductive loss and CSF ear leak."),
  step("Grading uses **House Brackmann** scale I (normal) to VI (total paralysis) for prognosis and trials. Incomplete eye closure risks exposure keratitis needing ophthalmology. Aberrant regeneration later causes synkinesis and crocodile tears (gustatory lacrimation) when fibres regrow to wrong targets. Chronic palsy rehabilitation includes gold weights, static slings and botulinum for synkinesis.", "Grade palsy I to VI. Guard the cornea first. Late rewiring causes linked movements and tears while eating.")],
 ["Forehead involved means lower motor neuron lesion", "Bell palsy: steroids within 72 hours plus eye care", "Transverse temporal fracture: SNHL plus facial palsy", "House Brackmann grades I normal to VI total"],
 "Viral inflammation swells the nerve inside its narrowest bony segment compressing its blood supply; fracture fragments or haematoma injure directly, while regenerating axons misdirect to wrong muscles and glands.",
 ["Bell versus Ramsay Hunt (vesicles, prognosis)", "Central forehead sparing versus peripheral palsy", "Otogenic palsy versus idiopathic Bell palsy"],
 ["House Brackmann grading and eye examination", "MRI when atypical, slow or recurrent; audiometry", "CT temporal bone after trauma"],
 [mcq("bk2-ent-061", "Facial weakness sparing the forehead most likely localises where?", ["Facial nerve in mastoid", "Central (upper motor neuron) lesion", "Parotid gland", "Stylomastoid foramen"], 1, "Forehead muscles receive bilateral cortical supply so central lesions spare forehead wrinkling, while peripheral nerve lesions weaken the entire face including forehead. Sparing demands stroke pathway assessment.", ["Incorrect. Mastoid nerve lesion weakens forehead too.", "Correct. Forehead sparing means upper motor neuron lesion.", "Incorrect. Parotid lesions are peripheral pattern.", "Incorrect. Foramen exit lesion is lower motor neuron."], "Spare the forehead, suspect the brain."),
  mcq("bk2-ent-062", "Bell palsy treatment with best early evidence within 72 hours is what?", ["Antibiotics", "Corticosteroids plus eye protection", "Surgery for all", "No treatment ever"], 1, "Early prednisolone significantly raises complete recovery in Bell palsy; lubricants and night taping protect the cornea when blink fails. Antivirals alone lack benefit; surgery is exceptional.", ["Incorrect. No bacterial cause to treat.", "Correct. Early steroids and eye care.", "Incorrect. Decompression is rare selected case.", "Incorrect. Eye damage is preventable and steroids help."], "Steroids early, eye protected always."),
  mcq("bk2-ent-063", "House Brackmann grade VI means what?", ["Normal function", "Total facial paralysis", "Mild weakness", "Synkinesis only"], 1, "Grade I is normal and grade VI is total paralysis with no tone or movement; intermediate grades track partial recovery used in prognosis and studies.", ["Incorrect. Normal is grade I.", "Correct. VI equals total paralysis.", "Incorrect. Mild weakness is grade II.", "Incorrect. Synkinesis features in middle grades."], "One is normal, six is total."),
  mcq("bk2-ent-064", "Transverse temporal bone fracture typically causes which ear pattern?", ["Conductive loss, drum intact", "Sensorineural loss with vertigo and facial palsy", "Glue ear", "Otosclerosis pattern"], 1, "Transverse fractures cross otic capsule and meatus injuring cochlea, vestibule and facial nerve together. Longitudinal fractures instead follow canal causing conductive loss and CSF otorrhoea.", ["Incorrect. That is longitudinal or simple trauma pattern.", "Correct. Transverse: sensorineural plus nerve injury.", "Incorrect. Effusion is not fracture signature.", "Incorrect. Otosclerosis is non traumatic fixation."], "Across the capsule: deaf, dizzy, weak face."),
  mcq("bk2-ent-065", "Crocodile tears after facial palsy recovery result from what?", ["Lacrimal gland tumour", "Aberrant regeneration of salivary fibres to lacrimal gland", "Blocked tear duct", "Allergy"], 1, "Regrowing parasympathetic fibres meant for salivary glands misroute to lacrimal gland, so eating triggers tearing (gustatory lacrimation), a late aberrant regeneration sign like synkinesis.", ["Incorrect. Tumour causes mass not meal linked tears.", "Correct. Miswired regeneration causes crocodile tears.", "Incorrect. Blockage causes constant watering, not gustatory.", "Incorrect. Allergy itches bilaterally."], "Tears at meals mean fibres rewired wrongly."),
  mcq("bk2-ent-066", "Facial palsy with discharging cholesteatoma ear should be managed how?", ["Label Bell palsy and reassure", "Urgent ENT care for surgical source control", "Steroids alone outpatient", "Facial massage only"], 1, "Otogenic palsy means infection or cholesteatoma compresses or invades the nerve in its canal; urgent mastoid surgery assessment plus antibiotics protects nerve and brain. Bell is diagnosis of exclusion.", ["Incorrect. Ear disease excludes simple Bell label.", "Correct. Urgent surgical source control assessment.", "Incorrect. Steroids without source control risk spread.", "Incorrect. Massage does not remove cholesteatoma."], "Palsy plus cholesteatoma: operate the source urgently."),
  mcq("bk2-ent-067", "Most Bell palsy patients have which long term outcome?", ["Permanent total paralysis usually", "Good spontaneous recovery in majority", "Bilateral progression", "Need surgery routinely"], 1, "About 70 percent recover completely spontaneously and steroids raise that further; incomplete recovery leaves synkinesis or weakness in minority, worse with Ramsay Hunt and diabetes.", ["Incorrect. Total permanent loss is minority outcome.", "Correct. Majority recover well.", "Incorrect. Bilateral palsy suggests other causes.", "Incorrect. Surgery is exceptional."], "Most Bell faces recover; Ramsay Hunt less so."),
  mcq("bk2-ent-068", "Inability to close the eye in facial palsy most urgently risks what?", ["Taste loss", "Exposure keratitis and corneal ulcer", "Hyperacusis", "Dry mouth"], 1, "Failed blink and Bell phenomenon insufficiency dry and abrade cornea toward ulcer and perforation, so lubrication, taping, moisture chambers and ophthalmology referral are urgent. Others are branch symptoms.", ["Incorrect. Taste loss is chorda tympani symptom.", "Correct. Corneal exposure is the urgent danger.", "Incorrect. Hyperacusis is stapedius branch sign, not emergency.", "Incorrect. Dry mouth follows gland fibre loss."], "Open eye in palsy: protect cornea first."),
  mcq("bk2-ent-069", "Hyperacusis in facial palsy localises lesion proximal to which branch?", ["Chorda tympani", "Nerve to stapedius", "Greater petrosal nerve", "Parotid branches"], 1, "Stapedius normally dampens loud sound; lesion at or above its branch removes the reflex causing hyperacusis, helping segment localisation along with taste and tearing tests historically.", ["Incorrect. Chorda lesion loses taste and salivation.", "Correct. Stapedius branch level gives hyperacusis.", "Incorrect. Greater petrosal affects tearing earlier.", "Incorrect. Parotid branches are distal motor only."], "Loud hurts when stapedius branch is out."),
  mcq("bk2-ent-070", "Slowly progressive facial palsy over months should prompt search for what?", ["Bell palsy", "Parotid or temporal bone tumour", "Viral cold", "Wax impaction"], 1, "Bell palsy peaks within days; progression beyond three weeks, recurrence, spasm or mass suggests neoplasm (parotid malignancy, schwannoma) needing imaging and referral, not idiopathic label.", ["Incorrect. Bell peaks in days, not months.", "Correct. Slow progression means tumour until excluded.", "Incorrect. Colds do not slowly paralyse.", "Incorrect. Wax never weakens facial nerve."], "Slow weak face equals tumour hunt.")]);

add("ent-hearing-rehab", "Hearing aids, cochlear implants and the deaf child", "hearing_rehabilitation_and_deaf_child", "Hearing Rehabilitation and the Deaf Child",
 ["Cochlear implant", "Hearing aids", "Bone anchored hearing", "Newborn hearing screening"],
 [step("Early hearing detection transforms language: congenital deafness missed past infancy delays speech irreversibly during critical brain plasticity windows. Universal newborn screening (otoacoustic emissions then auditory brainstem response) targets diagnosis by three months and intervention by six months (1-3-6 principle in many programmes). Any parental concern about hearing overrides passed screens.", "Find deaf babies by 3 months and help by 6 months. Parent worry always earns testing even after passed screens."),
  step("Causes of childhood deafness include genetic (connexin 26 GJB2 commonest non syndromic), congenital CMV infection, meningitis, prematurity with ototoxic exposure, and syndromes (Usher, Waardenburg, Pendred with goitre). Meningitis can ossify the cochlea within weeks, making implant timing urgent after bacterial meningitis deafness. Speech delay, inattention and television volume are late presentations.", "Genes and congenital CMV deafen most deaf children. After meningitis, cochlea may bone over fast: implant referral is urgent."),
  step("**Hearing aids** amplify sound for mild to severe losses with functioning hair cells, fitted and verified in growing ears with earmoulds and speech therapy support. Bone conduction devices bypass conductive blocks (atresia, chronic drainage) vibrating skull directly. Middle ear implants suit selected adults intolerant of moulds. Aids do not restore normal hearing; classroom acoustics and FM systems matter equally.", "Aids amplify for working inner ears. Bone vibrators bypass blocked middle ears. Classroom listening support counts as much as devices."),
  step("**Cochlear implants** bypass dead hair cells electrically stimulating the spiral ganglion directly, for severe to profound bilateral loss with limited aid benefit. Early implantation (often around or before 12 months in congenital deafness per local criteria) yields best spoken language. Surgery preserves facial nerve and electrodes thread the scala tympani; mapping and years of auditory verbal therapy follow.", "Implants electrically replace dead hair cells for profound deafness. Earlier in infancy means better spoken language.", cmp("Hearing aid", ["Amplifies acoustic sound", "Needs surviving hair cells", "Mild to severe losses", "Non surgical, removable"], "Cochlear implant", ["Electrical nerve stimulation", "Bypasses hair cells entirely", "Severe to profound, poor aid benefit", "Surgery plus lifelong mapping therapy"])),
  step("The deaf child needs whole team care: audiology, ENT, speech language therapy, teacher of the deaf, genetics and ophthalmology (Usher retina), plus family chosen communication (spoken, sign or both). Vaccination (pneumococcal, meningococcal where indicated) protects implant users from meningitis risk. Educational placement and assistive listening decide outcomes as much as device choice.", "Devices alone do not teach language: team, family communication choice and school support decide deaf children's futures.")],
 ["Screen newborns; diagnose by 3, intervene by 6 months", "GJB2 connexin 26 is commonest genetic deafness cause", "Meningitis deafness: urgent implant before cochlear ossification", "Implants bypass hair cells electrically for profound loss"],
 "Sound transduction fails from hair cell or conduction defects; electrical stimulation of spiral ganglion neurons restores auditory input during developmental plasticity windows that close progressively without stimulation.",
 ["Hearing aid versus implant by hair cell survival and severity", "Conductive atresia rehabilitation (bone device) versus sensorineural aid", "Congenital CMV versus genetic deafness clues"],
 ["Newborn OAE and automated ABR screening", "Diagnostic ABR and age appropriate audiometry", "CT and MRI cochlea and nerve before implantation; genetics and CMV testing"],
 [mcq("bk2-ent-071", "Universal newborn hearing programmes aim for diagnosis and intervention by which ages?", ["Diagnosis 1 year, help 2 years", "Diagnosis by 3 months, intervention by 6 months", "School entry testing", "Only if parents complain"], 1, "The 1-3-6 benchmark (screen by 1, diagnose by 3, intervene by 6 months) exploits early plasticity giving near normal language for many deaf infants. Waiting for speech delay forfeits this.", ["Incorrect. That misses critical language windows.", "Correct. Diagnose 3 months, intervene 6 months.", "Incorrect. School entry is far too late.", "Incorrect. Parental detection alone misses many cases."], "One, three, six: screen, diagnose, intervene."),
  mcq("bk2-ent-072", "Commonest genetic cause of non syndromic congenital deafness is mutation in what?", ["MITF only", "GJB2 encoding connexin 26", "Usherin alone", "Pendrin only"], 1, "GJB2 connexin 26 gap junction mutations cause most autosomal recessive non syndromic deafness worldwide. Pendrin gives Pendred syndrome with goitre; Usher adds retinitis pigmentosa.", ["Incorrect. MITF features in Waardenburg spectrum.", "Correct. Connexin 26 GJB2 is commonest.", "Incorrect. Usherin causes syndromic Usher disease.", "Incorrect. Pendrin is syndromic with thyroid features."], "Connexin 26 deafens most inherited non syndromic ears."),
  mcq("bk2-ent-073", "Child deafened by bacterial meningitis needs urgent implant referral because of what risk?", ["Cochlear ossification closing electrode path", "Wax formation", "Drum perforation", "Adenoid growth"], 1, "Labyrinthitis ossificans can ossify cochlear turns within weeks after meningitis, blocking electrode insertion, so implant assessment is urgent. Imaging tracks ossification progression.", ["Incorrect. Wax is irrelevant canal debris.", "Correct. Ossification races electrode insertion.", "Incorrect. Drums usually intact in meningitic deafness.", "Incorrect. Adenoids do not affect cochlea."], "Post meningitis: implant before bone fills cochlea."),
  mcq("bk2-ent-074", "Cochlear implants work by which principle?", ["Amplifying sound acoustically", "Direct electrical stimulation of spiral ganglion bypassing hair cells", "Vibrating skull bone", "Repairing ossicles"], 1, "External processor converts sound to electrical patterns delivered by scala tympani electrodes stimulating ganglion neurons directly, requiring an intact auditory nerve and prolonged auditory training.", ["Incorrect. Amplification is hearing aid principle.", "Correct. Electrical bypass of dead hair cells.", "Incorrect. Bone vibration is bone conduction device.", "Incorrect. Ossiculoplasty repairs conductive chain."], "Implant talks electricity straight to the nerve."),
  mcq("bk2-ent-075", "Profound bilateral deaf infant gains best spoken language when implanted when?", ["After age 10 years", "Early, around first year where criteria met", "Only after failing school", "In adulthood electively"], 1, "Auditory cortex plasticity peaks in infancy; implantation around 9 to 12 months (local criteria) with therapy gives best spoken language trajectories. Late implantation still helps but with limits.", ["Incorrect. Decade delay wastes plasticity.", "Correct. Early infancy implantation is best.", "Incorrect. School failure is preventable harm.", "Incorrect. Adult implantation follows different indications."], "Implant early while brain wires for sound."),
  mcq("bk2-ent-076", "Bone anchored hearing device is best suited for which child?", ["Profound sensorineural loss", "Canal atresia with conductive loss and good cochlea", "Glue ear one month", "Noise notch"], 1, "Bone conduction vibrates skull bypassing atretic canal and middle ear to a normal cochlea, ideal for atresia or chronically draining ears unfit for aids. Profound sensorineural loss needs implant assessment.", ["Incorrect. Profound cochlear loss needs implant pathway.", "Correct. Atresia with good cochlea suits bone device.", "Incorrect. Transient glue ear gets observation.", "Incorrect. Noise loss uses conventional aids if needed."], "Blocked road, good cochlea: vibrate the bone."),
  mcq("bk2-ent-077", "Pendred syndrome combines sensorineural deafness with what later feature?", ["Retinitis pigmentosa", "Goitre (thyroid enlargement)", "White forelock", "Blue sclera"], 1, "Pendrin (SLC26A4) defects cause enlarged vestibular aqueduct deafness with later euthyroid goitre in Pendred syndrome. Usher adds retinitis; Waardenburg pigment changes; osteogenesis imperfecta blue sclera.", ["Incorrect. Retinal disease marks Usher syndrome.", "Correct. Goitre follows in Pendred.", "Incorrect. White forelock is Waardenburg.", "Incorrect. Blue sclera is osteogenesis imperfecta."], "Deafness plus goitre equals Pendred."),
  mcq("bk2-ent-078", "Hearing aids primarily help when which structures survive?", ["Ossicles only", "Cochlear hair cells (sensory function)", "Facial nerve", "Semicircular canals"], 1, "Amplified sound still needs hair cells to transduce; when they are largely dead and loss profound, aids give inadequate benefit and implants are assessed. Ossicular defects may suit surgery or bone devices.", ["Incorrect. Ossicle loss can use bone routes.", "Correct. Aids need surviving hair cells.", "Incorrect. Facial nerve is motor, unrelated.", "Incorrect. Canals govern balance, not amplification."], "No hair cells, no use amplifying: implant instead."),
  mcq("bk2-ent-079", "Congenital CMV deafness may present how after passed newborn screen?", ["Never later", "Progressive or late onset sensorineural loss", "Conductive wax loss", "Otosclerosis in infancy"], 1, "Congenital cytomegalovirus, a leading non genetic cause, can pass screening then deteriorate progressively, needing audiologic surveillance in infected infants. Early urine PCR (first weeks) proves congenital timing.", ["Incorrect. Late progression is characteristic risk.", "Correct. CMV loss can arrive or worsen later.", "Incorrect. Wax is transient conductive, unrelated.", "Incorrect. Otosclerosis presents in young adults."], "CMV deafness can sneak in after the screen."),
  mcq("bk2-ent-080", "Parents suspect deafness despite passed newborn screen. Correct action is what?", ["Reassure discharge", "Refer for diagnostic audiology promptly", "Wait for school test", "Fit aid without testing"], 1, "Parental concern is a sensitive indicator and screening misses late onset or progressive losses, so prompt diagnostic audiology (ABR and behavioural) is mandatory at any age of concern.", ["Incorrect. Reassurance risks language delay.", "Correct. Test promptly on parental concern.", "Incorrect. School age is too late for intervention windows.", "Incorrect. Devices require measured thresholds."], "Parents worried about hearing are right until tested.")]);

add("ent-ear-tumours", "Tumours of the ear and cerebellopontine angle", "ear_and_cpa_tumours", "Tumours of the Ear and Cerebellopontine Angle",
 ["Vestibular schwannoma", "Glomus tumours", "Cerebellopontine angle", "NF2"],
 [step("Cerebellopontine angle tumours present with unilateral sensorineural deafness, tinnitus and imbalance long before mass effects betray them. **Vestibular schwannoma** forms about four fifths of angle tumours, growing from Schwann cells of the vestibular nerve in the internal meatus and expanding medially to compress trigeminal, facial and brainstem structures in that order of clinical appearance.", "Angle tumours whisper through one deaf ear years before pressing the brainstem. Most are vestibular schwannomas."),
  step("Growth is usually slow (millimetres yearly) and many small tumours in older patients never need intervention. Serial MRI surveillance with hearing preservation intent guides modern care: microsurgery (hearing preservation or translabyrinthine sacrifice approaches) and stereotactic radiosurgery compete by size, hearing status and patient preference, while facial nerve preservation is the universal surgical priority metric.", "Many angle tumours are watched with scans. Surgery or focused radiation follows growth, size and hearing: saving facial movement outranks all."),
  step("**Glomus tumours** (paragangliomas) arise from paraganglia along the jugular bulb (glomus jugulare) or middle ear promontory (tympanicum), causing pulsatile tinnitus synchronised with heartbeat and conductive loss, with a red retrotympanic mass blanching on pressure (Brown sign). They secrete catecholamines rarely; imaging shows moth eaten jugular foramen in jugulare disease. Embolisation plus surgery or radiotherapy treats by extent.", "Pulsatile tinnitus with red mass behind drum means glomus tumour. Jugular types eat the jugular foramen bone."),
  step("Meningiomas form the second angle tumour, arising from dura with broad base and dural tail on MRI, often preserving hearing longer relative to size. Epidermoid cysts insinuate with diffusion restriction on MRI and chemical meningitis risk if ruptured. Facial nerve schwannomas mimic vestibular ones but add facial twitch or palsy earlier.", "Dural based angle mass with tail is meningioma. Diffusion bright insinuating lesion is epidermoid."),
  step("External and middle ear malignancy is rarer: squamous carcinoma of canal or middle ear in chronically discharging ears causes pain, bleeding and facial palsy with poor prognosis needing radical resection and radiotherapy. Basal and squamous cancers of pinna follow sun exposure like skin cancers elsewhere, with perichondrial spread making cartilage resection margins important.", "Bleeding painful chronic ear with palsy may be cancer, not infection. Sun cancers of pinna need cartilage aware margins.")],
 ["Unilateral SNHL plus tinnitus: MRI excludes schwannoma", "Pulsatile tinnitus plus red retrotympanic mass equals glomus", "Meningioma is second commonest CPA tumour with dural tail", "Facial preservation is prime surgical metric in CPA surgery"],
 "Slow Schwann cell proliferation expands the meatus and angle cistern compressing cochlear nerve first; paraganglioma vascular nests grow along skull base foramina eroding bone while fed by ascending pharyngeal vessels.",
 ["Schwannoma versus meningioma imaging (meatal expansion versus dural tail)", "Glomus tympanicum (middle ear only) versus jugulare (foramen erosion)", "Epidermoid diffusion restriction versus arachnoid cyst following CSF"],
 ["Gadolinium MRI internal meatus and CPA", "CT temporal bone for glomus bone erosion; angiography and embolisation planning", "Audiometry and facial grading serially"],
 [mcq("bk2-ent-081", "Commonest cerebellopontine angle tumour is which?", ["Meningioma", "Vestibular schwannoma", "Epidermoid", "Metastasis"], 1, "Vestibular (acoustic) schwannoma accounts for roughly 80 percent of angle tumours, arising in the internal meatus from vestibular nerve Schwann cells. Meningioma is second.", ["Incorrect. Meningioma is second commonest.", "Correct. Vestibular schwannoma dominates CPA.", "Incorrect. Epidermoid is uncommon.", "Incorrect. Metastases rarely isolate to angle."], "Eight in ten angle tumours are schwannomas."),
  mcq("bk2-ent-082", "Pulsatile tinnitus synchronous with pulse and red mass behind drum indicate what?", ["Otosclerosis Schwartze sign", "Glomus tumour (paraganglioma)", "Cholesteatoma", "Glue ear"], 1, "Vascular paraganglioma visible through drum causes pulsatile tinnitus and conductive loss; pressure blanching (Brown sign) supports it. Biopsy is avoided; imaging and embolisation plan treatment.", ["Incorrect. Schwartze blush is faint pink without pulsatile tinnitus mass.", "Correct. Glomus tumour until proven otherwise.", "Incorrect. Cholesteatoma is white keratin with foul discharge.", "Incorrect. Effusion dulls drum without vascular mass."], "Red drum mass pulsing with heartbeat: glomus, do not biopsy."),
  mcq("bk2-ent-083", "In vestibular schwannoma surgery, outcome prioritised above hearing is what?", ["Taste preservation", "Facial nerve function preservation", "Balance restoration", "Tinnitus cure"], 1, "Facial paralysis devastates eye, face and social function, so facial preservation rates headline surgical series, with hearing preservation attempted only in selected small tumours and favourable approaches.", ["Incorrect. Taste via chorda is minor morbidity.", "Correct. Facial function outranks hearing.", "Incorrect. Vestibular loss compensates centrally usually.", "Incorrect. Tinnitus often persists despite surgery."], "Save the face first in angle surgery."),
  mcq("bk2-ent-084", "MRI dural tail with broad dural based CPA mass suggests which tumour?", ["Schwannoma", "Meningioma", "Glomus jugulare", "Cholesterol granuloma"], 1, "Meningiomas arise from dura showing broad base, dural tail and calcification, often eccentric to meatus. Schwannomas centre on and expand the meatus instead.", ["Incorrect. Schwannoma expands meatus without dural tail.", "Correct. Dural tail means meningioma.", "Incorrect. Glomus centres on jugular foramen below.", "Incorrect. Granuloma is petrous apex blood product lesion."], "Tail on dura points to meningioma."),
  mcq("bk2-ent-085", "Small asymptomatic vestibular schwannoma in 75 year old most often managed how initially?", ["Immediate radical surgery", "Watch and wait serial MRI surveillance", "Chemotherapy", "Emergency radiation"], 1, "Many small tumours grow slowly or not at all, so surveillance MRI with intervention only on growth or symptoms spares elderly patients surgical risk. Chemotherapy has no routine role.", ["Incorrect. Surgery risks outweigh in stable elderly disease.", "Correct. Serial MRI watch and wait.", "Incorrect. No standard chemotherapy exists.", "Incorrect. Radiosurgery follows documented growth decisions."], "Old patient, small stable tumour: scan and watch."),
  mcq("bk2-ent-086", "Glomus jugulare characteristically erodes which skull base structure on CT?", ["Mastoid tip only", "Jugular foramen with moth eaten margins", "Oval window", "Cribriform plate"], 1, "Jugulare paragangliomas expand the jugular foramen with irregular moth eaten bone destruction and may invade middle ear from below, unlike tympanicum confined to promontory. Lower cranial nerves suffer as it grows.", ["Incorrect. Tip erosion is mastoiditis pattern.", "Correct. Moth eaten jugular foramen.", "Incorrect. Oval window is otosclerosis site.", "Incorrect. Cribriform is anterior skull base olfactory area."], "Moth eaten jugular hole equals glomus jugulare."),
  mcq("bk2-ent-087", "Epidermoid cyst of CPA is best distinguished on MRI by what?", ["Dural tail", "Diffusion restriction (bright DWI)", "Meatal expansion", "Flow voids"], 1, "Keratinaceous epidermoid restricts diffusion brightly unlike CSF following arachnoid cysts, and insinuates around nerves and vessels. It lacks dural base and meatal origin signs.", ["Incorrect. Tail belongs to meningioma.", "Correct. Bright diffusion means epidermoid.", "Incorrect. Meatal expansion is schwannoma.", "Incorrect. Flow voids mark vascular malformations."], "Diffusion bright angle lesion: epidermoid."),
  mcq("bk2-ent-088", "As CPA tumours enlarge beyond cochlear symptoms, which nerve signs appear next classically?", ["Optic atrophy first", "Trigeminal sensory loss and reduced corneal reflex", "Hypoglossal palsy first", "Olfactory loss"], 1, "Expanding angle masses reach trigeminal nerve in Meckel region causing facial numbness and lost corneal reflex before facial weakness (nerve resists stretch) and later lower cranial or brainstem signs.", ["Incorrect. Optic pathway is distant anterior.", "Correct. Trigeminal signs follow cochlear.", "Incorrect. Hypoglossal is late lower extension.", "Incorrect. Smell is frontal base territory."], "Numb cheek after deaf ear: tumour growing."),
  mcq("bk2-ent-089", "Chronically discharging ear now with pain, bleeding and facial palsy raises concern for what?", ["Simple CSOM flare", "Squamous carcinoma of middle ear or canal", "Wax impaction", "Glue ear"], 1, "Malignancy arising in chronic ears changes painless discharge to painful bleeding mass with nerve invasion, needing biopsy (unlike glomus) imaging and radical treatment planning.", ["Incorrect. Flares discharge without bleeding mass and palsy pattern.", "Correct. Carcinoma complicating chronic ear.", "Incorrect. Wax never paralyses facial nerve.", "Incorrect. Effusion has intact drum without discharge."], "Pain plus blood plus palsy in chronic ear: biopsy for cancer."),
  mcq("bk2-ent-090", "Brown sign in glomus tympanicum examination refers to what?", ["Drum perforates on pressure", "Red mass blanches with pneumatic pressure", "Discharge turns brown", "Hearing improves with pressure"], 1, "Pneumatic otoscopy pressure blanches the vascular retrotympanic mass (Brown sign) supporting paraganglioma. It is a gentle diagnostic observation, never biopsy or forceful probing.", ["Incorrect. Perforation is trauma, not this sign.", "Correct. Blanching red mass on pressure.", "Incorrect. Discharge colour is unrelated sign.", "Incorrect. Hearing change is not the sign."], "Press gently, red fades: Brown sign of glomus.")]);
add("ent-septum-external-nose", "External nose, nasal septum and choanal atresia", "external_nose_septum_choanal", "External Nose, Nasal Septum and Choanal Atresia",
 ["Deviated nasal septum", "Septal haematoma", "Choanal atresia", "Nasal fracture"],
 [step("The external nose is skin over upper lateral, lower lateral (alar) cartilages and nasal bones, vulnerable to trauma and sun cancers. Inside, the **septum** (quadrilateral cartilage, perpendicular plate, vomer) divides airflow; deviations are near universal but matter when they obstruct, cause contact headache points or block sinus surgery access. Little area on the anterior septum hosts Kiesselbach plexus.", "Most septums deviate slightly. Trouble starts when deviation blocks airflow, sinuses or surgery. Front septum vessels bleed easily."),
  step("Nasal fractures are clinical diagnoses (deformity, swelling, epistaxis, septal haematoma) needing assessment within hours for haematoma and after swelling settles (about a week) for closed reduction window (roughly two weeks adults). **Septal haematoma** must be drained urgently: blood strips cartilage of perichondrial nutrition causing necrosis, saddle nose and abscess risk, especially in children.", "Drain septal blood urgently or cartilage dies and nose saddles. Broken noses reduce best after swelling falls, within two weeks."),
  step("Septal perforations follow surgery, trauma, nose picking, cocaine or granulomatous disease (granulomatosis with polyangiitis), presenting with crusting, whistling and epistaxis. Small symptomatic holes get humidification and obturators; surgery closes selected larger ones. Cocaine and vasculitis must stop or be treated before repair attempts.", "Septal holes whistle and crust. Cocaine and vasculitis cause them and must be controlled before any closure works."),
  step("**Choanal atresia** blocks the posterior nasal airway by bony or membranous plate: bilateral disease distresses neonates (obligate nose breathers) with cyclical cyanosis relieved by crying, failing nasogastric tube passage, while unilateral disease presents later with one sided discharge. CHARGE association links choanal atresia with coloboma, heart, growth and ear anomalies. Endoscopic perforation and stenting opens the airway.", "Newborn blue when quiet, pink when crying, tube will not pass: bilateral choanal atresia. Open it endoscopically."),
  step("Septoplasty straightens obstructing septum preserving cartilage support (L strut) to avoid saddle; submucosal resection is largely historical for deforming support. Rhinoplasty reshapes external framework for form and function combined. Postoperative packs, splints and saline irrigation support healing; septal perforation and saddle are counselled risks.", "Modern septoplasty preserves support struts to prevent saddling while straightening the airway.")],
 ["Septal haematoma: drain urgently or saddle nose follows", "Bilateral choanal atresia: cyanosis relieved by crying in neonate", "Kiesselbach plexus sits on anterior septum (Little area)", "Septoplasty preserves L strut support"],
 "Cartilage survives on perichondrial blood flow, so haematoma or abscess separates and necroses it; embryonic buccopharyngeal membrane persistence plates the choana, while deviated growth between cartilage and bone bows the septum.",
 ["Septal haematoma versus abscess (pain, fever)", "Deviated septum versus turbinate hypertrophy on decongestion", "Choanal atresia versus neonatal respiratory distress other causes"],
 ["Nasal endoscopy and septal examination after trauma", "CT sinuses and choanae for atresia and surgical planning", "ANCA and drug history for perforation workup"],
 [mcq("bk2-ent-091", "Child after nasal trauma with boggy bilateral septal swelling needs what urgently?", ["Discharge home one week", "Urgent drainage of septal haematoma", "Nasal packing only", "Reassurance"], 1, "Septal haematoma strips cartilage nutrition causing necrosis, saddle deformity and abscess; prompt incision drainage plus packing and antibiotics prevents cartilage loss. Delay deforms growing noses.", ["Incorrect. Week delay necroses cartilage.", "Correct. Drain septal haematoma urgently.", "Incorrect. Packing without drainage traps blood.", "Incorrect. Boggy septum after trauma is haematoma until drained."], "Boggy septum after blow: drain today."),
  mcq("bk2-ent-092", "Neonate cyanosed when quiet, pink when crying, NG tube will not pass nose suggests what?", ["Laryngomalacia", "Bilateral choanal atresia", "Tracheo-oesophageal fistula", "Meconium aspiration"], 1, "Obligate nasal breathing infants suffocate with bilateral choanal block and relieve by mouth breathing when crying; failed tube passage confirms nasal obstruction needing airway and endoscopic opening.", ["Incorrect. Laryngomalacia stridors without tube failure pattern.", "Correct. Bilateral choanal atresia classic picture.", "Incorrect. Fistula chokes with feeds and distends abdomen.", "Incorrect. Aspiration distresses continuously from birth."], "Blue quiet, pink crying newborn: blocked choanae."),
  mcq("bk2-ent-093", "CHARGE association includes choanal atresia plus which features?", ["Cardiac defects, coloboma and ear anomalies", "Goitre only", "Polydactyly only", "Renal cysts only"], 0, "CHARGE: Coloboma, Heart defects, Atresia choanae, Retarded growth, Genital and Ear anomalies, so atresia babies need cardiology, eye and hearing assessment. Others are isolated distractors.", ["Correct. Heart, eye and ear anomalies accompany atresia.", "Incorrect. Goitre belongs to Pendred hearing syndrome.", "Incorrect. Polydactyly alone does not define CHARGE.", "Incorrect. Renal cysts point elsewhere (for example VACTERL renal)."], "Atretic choanae: check heart, eyes and ears."),
  mcq("bk2-ent-094", "Septal perforation with saddle nose, epistaxis and systemic illness suggests which systemic cause?", ["Allergic rhinitis", "Granulomatosis with polyangiitis", "Simple deviation", "Acute sinusitis"], 1, "Vasculitic septal destruction with saddle, crusting and pulmonary renal disease marks granulomatosis with polyangiitis (ANCA associated), needing systemic workup before local repair. Cocaine is the other classic cause.", ["Incorrect. Allergy sneezes without destroying septum.", "Correct. Vasculitis destroys septum and saddles nose.", "Incorrect. Deviation bows but does not perforate systemically.", "Incorrect. Sinusitis is acute infection without saddle."], "Perforated saddle nose plus systemic signs: vasculitis."),
  mcq("bk2-ent-095", "Closed reduction of nasal fracture is best timed when?", ["Always immediately under swelling", "After swelling settles, within about 2 weeks", "After 3 months", "Never manipulate"], 1, "Reducing after oedema falls (days) but before bone sets (about 2 weeks adults, sooner children) restores alignment accurately. Septal haematoma alone cannot wait for this window.", ["Incorrect. Swelling hides true alignment.", "Correct. After swelling, before union sets.", "Incorrect. Months later needs osteotomy surgery.", "Incorrect. Displaced fractures benefit from timely reduction."], "Wait days for swelling, not weeks for setting."),
  mcq("bk2-ent-096", "Whistling on breathing with crusting and nosebleeds suggests which septal lesion?", ["Septal haematoma", "Septal perforation", "Deviated spur only", "Choanal polyp"], 1, "Air through a septal hole whistles while turbulent drying crusts and bleeds; causes include surgery, cocaine and vasculitis. Examination and cause control precede obturator or closure decisions.", ["Incorrect. Haematoma is acute boggy swelling.", "Correct. Perforation whistles and crusts.", "Incorrect. Spurs obstruct without whistling hole.", "Incorrect. Choanal polyps block posteriorly without whistle."], "Nose that whistles has a hole in it."),
  mcq("bk2-ent-097", "Unilateral choanal atresia typically presents how in childhood?", ["Neonatal cyanosis", "Persistent one sided nasal discharge and blockage", "Bilateral anosmia", "Recurrent epistaxis only"], 1, "One open side sustains breathing, so unilateral atresia declares later as single sided mucoid discharge and obstruction, sometimes found at adenoid or sinus assessment. Bilateral disease is neonatal emergency.", ["Incorrect. Cyanosis marks bilateral neonatal block.", "Correct. One sided discharge in child.", "Incorrect. Smell loss is bilateral mucosal disease clue.", "Incorrect. Bleeding alone points to vessels or masses."], "One blocked nostril since childhood: unilateral atresia."),
  mcq("bk2-ent-098", "Septoplasty preserves which structure to prevent saddle deformity?", ["Vomer removal completely", "Dorsal and caudal L strut of cartilage", "Alar cartilages", "Nasal bones"], 1, "Retaining an L shaped dorsal caudal cartilage strut maintains nasal support while deviated central cartilage is corrected; over resection (old SMR) risked saddle and tip collapse.", ["Incorrect. Vomer work does not support dorsum.", "Correct. Preserve the L strut.", "Incorrect. Alar cartilages shape tip, not septal support strut.", "Incorrect. Bones support upper third only."], "Keep the L, keep the nose shape."),
  mcq("bk2-ent-099", "Most nasal septal deviations cause which management need?", ["Universal surgery", "None when asymptomatic; treat only obstruction or access problems", "Lifelong steroids", "Packing"], 1, "Minor deviations are normal anatomy; surgery follows symptomatic obstruction failing medical therapy, contact symptoms or surgical access needs, not radiographic deviation alone.", ["Incorrect. Imaging deviation alone never mandates surgery.", "Correct. Treat symptoms, not scans.", "Incorrect. Steroids treat mucosal rhinitis, not bone shape.", "Incorrect. Packing treats bleeding acutely."], "Operate on blocked patients, not bent pictures."),
  mcq("bk2-ent-100", "Anterior septal bleeding site Kiesselbach plexus lies in which named area?", ["Little area", "Posterior choana", "Middle meatus", "Olfactory cleft"], 0, "Little area on anterior inferior septum hosts Kiesselbach plexus anastomosis, source of most epistaxis and target of pressure and cautery. Posterior bleeds arise deeper from sphenopalatine branches.", ["Correct. Little area anterior septum.", "Incorrect. Choana is posterior outlet.", "Incorrect. Meatus drains sinuses laterally.", "Incorrect. Olfactory cleft is superior smell region."], "Front septum plexus is Little area.")]);

add("ent-epistaxis", "Epistaxis", "epistaxis_management", "Epistaxis",
 ["Epistaxis", "Kiesselbach plexus", "Sphenopalatine artery", "Nasal packing"],
 [step("Most nosebleeds arise anteriorly from **Kiesselbach plexus** in Little area where septal vessels anastomose superficially, provoked by picking, dry air, rhinitis and trauma, especially in children and young adults. Anterior bleeds ooze from one nostril and yield to pressure. Posterior bleeds (sphenopalatine territory) in older hypertensive or anticoagulated patients run down the throat, resist pressure and threaten airway and blood loss.", "Front bleeds drip out and squeeze shut. Back bleeds pour down throats of older patients and endanger airways."),
  step("First aid is universal and examined: sit up leaning **forward**, pinch the soft nose (not bony bridge) continuously for 10 to 15 minutes, spit blood, breathe through mouth, and avoid blowing afterwards. Ice adds little. Failure proceeds to examination with suction, vasoconstrictor and anaesthetic spray, then silver nitrate cautery only to a visible anterior point and never both septal sides at once (perforation risk).", "Lean forward, pinch soft nose fifteen minutes. Cauterise one septal side only or you perforate it."),
  step("Persistent bleeding needs packing: absorbable materials or inflatable anterior packs, and posterior packs or balloons for back bleeds with admission, oxygen monitoring and antibiotics per protocol because of toxic shock and hypoxia risks. Check haemoglobin, coagulation and anticoagulant burden (warfarin, DOACs, antiplatelets) and blood pressure after control, not as substitute for local control.", "Packed noses (especially posterior) get admitted and monitored. Check blood count, clotting drugs and pressure after stopping flow.", tbl(["Feature", "Anterior bleed", "Posterior bleed"], [["Typical patient", "Child, young adult", "Older, hypertensive, anticoagulated"], ["Flow", "Out one nostril", "Down throat, both sides"], ["First control", "Pressure, cautery", "Packing, admission, artery control"], ["Site", "Kiesselbach plexus", "Sphenopalatine branches"]])),
  step("Refractory bleeds escalate to endoscopic **sphenopalatine artery** ligation or cautery in theatre, anterior ethmoid control for high bleeds, and interventional embolisation in selected patients unfit or failing surgery (stroke and blindness risks counselled). Ligation has largely replaced external carotid approaches. Hereditary haemorrhagic telangiectasia and tumours (juvenile angiofibroma in adolescent males) underlie recurrent patterns needing specialist pathways.", "Unstoppable back bleeds get the sphenopalatine artery tied endoscopically. Teenage boys with recurrent bleeds may harbour angiofibroma."),
  step("Recurrent unilateral bleeds with obstruction demand nasendoscopy for tumours, septal spurs or telangiectasia; blood dyscrasia workup follows bilateral recurrent childhood patterns. Discharge advice (no blowing, sneezing open mouth, humidification, petroleum jelly) prevents early rebleeds. Anticoagulants are restarted by balancing thrombotic risk with cardiology or haematology input.", "One sided recurrent bleeds need scope for lumps. Restart blood thinners by balancing clot versus bleed with specialists.")],
 ["Pinch soft nose leaning forward 15 minutes first", "Never cauterise both septal sides simultaneously", "Posterior packs admit: hypoxia and toxic shock risks", "SPA ligation controls refractory posterior bleeds"],
 "Superficial septal plexus vessels rupture with mucosal drying and trauma, while posterior arterial branches bleed under higher pressure into the pharynx; coagulopathy and hypertension aggravate but rarely initiate bleeding.",
 ["Anterior versus posterior bleed by flow direction and age", "HHT telangiectasia versus local vessel bleed", "Juvenile angiofibroma in adolescent male recurrent bleeds"],
 ["Nasendoscopy after first aid control", "Full blood count, coagulation and group and hold when severe", "CT angiography or angiography for refractory cases"],
 [mcq("bk2-ent-101", "Correct first aid position and pressure for epistaxis is what?", ["Lie back, pinch bony bridge", "Sit leaning forward, pinch soft nose 10 to 15 minutes", "Tilt head back swallow blood", "Blow nose forcefully first"], 1, "Forward lean prevents swallowing and airway soiling while soft part compression squeezes Kiesselbach plexus against septum. Bony bridge pressure compresses nothing useful; head back hides swallowed blood loss.", ["Incorrect. Lying back soils airway and bridge pinch misses vessels.", "Correct. Forward lean, soft pinch, timed pressure.", "Incorrect. Swallowed blood vomits and hides loss.", "Incorrect. Blowing dislodges clot and worsens bleed."], "Forward, soft, fifteen: the first aid triad."),
  mcq("bk2-ent-102", "Why must silver nitrate cautery never be applied to both septal sides at same session?", ["It stains teeth", "Opposing cautery necroses cartilage causing perforation", "It causes anosmia always", "It raises blood pressure"], 1, "Septal cartilage feeds from overlying perichondrium on both sides; bilateral burns devascularise it producing perforation. Stage the sides weeks apart if both truly need treatment.", ["Incorrect. Staining is trivial skin effect.", "Correct. Bilateral cautery perforates septum.", "Incorrect. Smell area is superior, cautery is anterior inferior.", "Incorrect. No pressor effect from local cautery."], "One side only: two burns make a hole."),
  mcq("bk2-ent-103", "Older hypertensive man bleeding down throat despite anterior pack most likely bleeds from where?", ["Kiesselbach plexus", "Sphenopalatine artery territory (posterior)", "Alar skin", "Inferior turbinate front"], 1, "Posterior bleeds from sphenopalatine branches in Woodruff area course down pharynx in older patients and escape anterior measures, needing posterior packing or SPA control and admission.", ["Incorrect. Anterior plexus bleeds out the nostril and cautery reaches it.", "Correct. Posterior sphenopalatine source.", "Incorrect. Skin bleeds externally visibly.", "Incorrect. Front turbinate bleeds anteriorly."], "Down the throat in old age equals posterior source."),
  mcq("bk2-ent-104", "Posterior nasal packs require admission mainly due to which risks?", ["Anosmia", "Hypoxia, airway and toxic shock complications", "Septal perforation only", "Hearing loss"], 1, "Posterior packs can obstruct airway, trigger nasopulmonary reflex hypoxia (especially elderly, lung disease) and rarely toxic shock, so monitored admission with oxygen checks is standard.", ["Incorrect. Smell loss is not the admission driver.", "Correct. Airway, hypoxia and toxic shock risks.", "Incorrect. Perforation follows cautery or trauma more.", "Incorrect. Ears unaffected by posterior packs."], "Back pack in place means bed and monitor."),
  mcq("bk2-ent-105", "Definitive endoscopic control for refractory posterior epistaxis targets which artery?", ["Anterior ethmoid only", "Sphenopalatine artery at its foramen", "External carotid in neck routinely", "Facial artery"], 1, "Endoscopic SPA ligation or cautery at sphenopalatine foramen (crista ethmoidalis landmark) controls most refractory posterior bleeds with high success, largely replacing external carotid ligation.", ["Incorrect. Ethmoid control suits high anterior bleeds.", "Correct. Ligate sphenopalatine artery endoscopically.", "Incorrect. Neck ligation is historical backup.", "Incorrect. Facial artery supplies lip and alar region."], "Tie the sphenopalatine and back bleeds stop."),
  mcq("bk2-ent-106", "Adolescent boy with recurrent unilateral epistaxis and nasal obstruction should be imaged for what before biopsy?", ["Inverted papilloma", "Juvenile nasopharyngeal angiofibroma", "Antrochoanal polyp biopsy blindly", "Septal spur"], 1, "Vascular angiofibroma in teenage males bleeds recurrently and must be imaged (CT/MRI with angiographic assessment) before any biopsy, which can haemorrhage catastrophically; resection follows embolisation planning.", ["Incorrect. Papilloma affects older adults.", "Correct. Angiofibroma: image, never blind biopsy.", "Incorrect. Polyps do not bleed this vascular pattern and biopsy still needs imaging first.", "Incorrect. Spurs bleed mildly and are visible directly."], "Teen boy, blocked bleeding nose: image, do not biopsy."),
  mcq("bk2-ent-107", "Recurrent epistaxis with lip and tongue telangiectasia and family history suggests what?", ["Von Willebrand only", "Hereditary haemorrhagic telangiectasia", "Scurvy", "Hypertension alone"], 1, "HHT (Osler Weber Rendu) gives mucocutaneous telangiectasia (lips, tongue, fingers), recurrent epistaxis and visceral arteriovenous malformations with autosomal dominant inheritance, needing systemic screening.", ["Incorrect. Von Willebrand lacks telangiectasia spots.", "Correct. HHT telangiectasia pattern.", "Incorrect. Scurvy gives gum and perifollicular bleeding.", "Incorrect. Pressure aggravates but does not create spots."], "Spots on lips plus nosebleeds in family equals HHT."),
  mcq("bk2-ent-108", "Hypertension in acute epistaxis is best handled how?", ["Aggressive immediate lowering as primary cure", "Control bleeding locally first; treat severe pressure per medical assessment", "Ignore pressure entirely forever", "Sedate all patients"], 1, "Pressure often rises from pain and anxiety and rarely causes bleeds alone; local control comes first, then measured medical management of genuinely severe hypertension. Precipitate drops risk organ ischaemia.", ["Incorrect. Bleeding control is local, not pressure crash.", "Correct. Local control first, judged pressure care after.", "Incorrect. Severe sustained hypertension still needs care.", "Incorrect. Sedation is selective, not routine."], "Stop the nose first, then judge the pressure."),
  mcq("bk2-ent-109", "After successful cautery, which advice prevents early rebleeding?", ["Blow nose next day", "Avoid blowing, straining and hot showers; use humidification", "Stop all fluids", "Resume nose picking"], 1, "Protecting the eschar (no blowing, sneezing open mouthed, avoiding heat and straining, saline or ointment humidification) for about a week prevents clot disruption rebleeds.", ["Incorrect. Blowing shears the fresh eschar.", "Correct. Protect clot and humidify.", "Incorrect. Hydration helps mucosa; restriction harms.", "Incorrect. Picking restarts anterior bleeds."], "Leave the scab alone and keep it moist."),
  mcq("bk2-ent-110", "Embolisation for epistaxis is reserved selectively because of which feared complications?", ["Septal perforation", "Stroke and ophthalmic blindness via collateral vessels", "Anosmia only", "Pack infection"], 1, "External carotid branches anastomose with ophthalmic and cerebral circulations, so embolic stroke and blindness are rare but defining risks, reserving embolisation for surgical failures or unfit patients.", ["Incorrect. Perforation is cautery complication.", "Correct. Stroke and blindness from collaterals.", "Incorrect. Smell risk is minor by comparison.", "Incorrect. Infection relates to packing duration."], "Emboli can reach eye and brain: reserve it.")]);

add("ent-rhinitis-polyps", "Rhinitis and nasal polyps", "rhinitis_and_nasal_polyps", "Rhinitis and Nasal Polyps",
 ["Allergic rhinitis", "Nasal polyps", "Chronic rhinosinusitis", "Intranasal steroids"],
 [step("**Rhinitis** is nasal mucosal inflammation causing blockage, discharge, sneezing and itch. Allergic rhinitis divides seasonal (pollens) from perennial (house dust mite, animal dander) with IgE mediated mast cell degranulation producing immediate sneeze and late congestion; pale boggy turbinates and allergic crease support it. Non allergic, occupational, hormonal and drug induced (rhinitis medicamentosa from decongestant overuse) forms mimic it.", "Itchy sneezy watery nose with triggers means allergic rhinitis. Decongestant spray addiction causes its own rhinitis."),
  step("First line allergic therapy is allergen avoidance plus daily **intranasal corticosteroid** (correct aim outward technique), with non sedating antihistamines for sneeze and itch and saline irrigation as adjunct. Immunotherapy (subcutaneous or sublingual) modifies disease in severe selected cases with proven dominant allergen. Antibiotics treat no rhinitis without bacterial sinusitis evidence.", "Daily nasal steroid aimed outward is the backbone. Antihistamines help sneeze; immunotherapy reshapes severe allergy."),
  step("**Chronic rhinosinusitis** persists beyond twelve weeks with blockage, discharge, facial pain and smell loss, divided by polyp presence. Nasal polyps are pale grape like oedematous prolapses from ethmoid mucosa (middle meatus), bilateral usually, painless and insensate unlike red tender turbinates. Samter triad links polyps, asthma and aspirin sensitivity; cystic fibrosis and allergic fungal disease underlie selected cases.", "Pale painless grapes in both noses are polyps, not turbinates. Polyps plus asthma plus aspirin sensitivity is Samter triad."),
  step("Polyp and sinusitis care escalates from saline and intranasal steroids (drops or high volume delivery to sinuses) through short oral steroid bursts in severe polyp disease, to endoscopic sinus surgery opening drainage pathways when medical therapy fails, with biologics (anti IgE, IL4 or IL5 pathways) for recurrent severe polyps with asthma in specialist programmes. CT sinuses (Lund Mackay) plans surgery; it does not diagnose rhinitis.", "Steroids shrink polyps; surgery opens sinuses when sprays fail; biologics serve recurrent polyp asthma patients.", cmp("Nasal polyp", ["Pale, grey, insensate, mobile", "Arises middle meatus, usually bilateral", "Steroids shrink it", "Associated asthma, aspirin sensitivity"], "Inferior turbinate", ["Pink red, sensitive, bony core", "Fixed lateral wall structure", "Decongestants shrink it", "Normal anatomy, hypertrophies in rhinitis"])),
  step("Red flags rewrite the pathway: unilateral polyp or mass (antrochoanal polyp from maxillary sinus in youth, inverted papilloma or malignancy in older adults) needs imaging and biopsy pathway, orbital pain or swelling and neurological signs mean complicated sinusitis, and epistaxis dominant disease suggests vascular or neoplastic causes. Anosmia after viral infection (including post COVID) is usually mucosal or olfactory neuronal and often recovers with smell training.", "One sided polyp is not routine: image it. Eye swelling with sinusitis is an emergency, not rhinitis care.")],
 ["Intranasal steroid first line for allergic rhinitis and polyps", "Polyps are pale insensate; turbinates pink sensitive", "Samter triad: polyps, asthma, aspirin sensitivity", "Unilateral nasal mass needs tumour exclusion"],
 "Type 2 eosinophilic inflammation oedematously prolapses ethmoid mucosa into polyps in most Western disease, while IgE mast cell activation drives allergic symptoms; ostiomeatal obstruction then stagnates sinus mucus perpetuating infection and inflammation.",
 ["Allergic versus vasomotor rhinitis by itch, sneeze and triggers", "Polyp versus hypertrophied turbinate by colour and sensation", "Antrochoanal (unilateral, youth) versus ethmoid polyps (bilateral, adult)"],
 ["Nasendoscopy for polyps and masses", "CT paranasal sinuses for chronic sinusitis surgical planning", "Allergy testing when immunotherapy considered; smell testing"],
 [mcq("bk2-ent-111", "First line maintenance therapy for moderate allergic rhinitis is what?", ["Oral antihistamine alone daily forever", "Daily intranasal corticosteroid with correct technique", "Topical decongestant indefinitely", "Antibiotic courses"], 1, "Intranasal steroids control all allergic symptoms including congestion best and are first line maintenance; antihistamines adjunct for itch and sneeze. Chronic decongestant causes rebound medicamentosa.", ["Incorrect. Antihistamine alone undercontrols congestion.", "Correct. Daily intranasal steroid is backbone.", "Incorrect. Indefinite decongestant causes rhinitis medicamentosa.", "Incorrect. Antibiotics do not treat allergy."], "Nasal steroid daily beats all comers in allergy."),
  mcq("bk2-ent-112", "Rebound congestion after months of topical decongestant spray is called what?", ["Allergic rhinitis", "Rhinitis medicamentosa", "Atrophic rhinitis", "Vasomotor cure"], 1, "Prolonged vasoconstrictor use down regulates receptors causing rebound hyperaemia and spray dependence (rhinitis medicamentosa), treated by stopping spray with intranasal steroid cover.", ["Incorrect. Allergy has itch and trigger pattern without spray dependence.", "Correct. Spray induced rebound is medicamentosa.", "Incorrect. Atrophic rhinitis crusts with foetor and wide cavities.", "Incorrect. It worsens, not cures, vasomotor symptoms."], "Addicted nose spray creates its own blockage."),
  mcq("bk2-ent-113", "Pale painless insensate grape like masses in middle meatus bilaterally are what?", ["Inferior turbinates", "Nasal polyps", "Antrochoanal polyp solitary", "Septal haematoma"], 1, "Ethmoid polyps are oedematous pale prolapses, bilateral and insensate, distinguishing them from pink sensitive turbinates which should never be biopsied or removed as polyps.", ["Incorrect. Turbinates are pink, sensitive and fixed.", "Correct. Bilateral pale grapes are polyps.", "Incorrect. Antrochoanal is solitary from maxillary sinus.", "Incorrect. Haematoma is septal boggy swelling post trauma."], "Pale and numb equals polyp; pink and tender equals turbinate."),
  mcq("bk2-ent-114", "Samter triad comprises nasal polyps, asthma and sensitivity to what?", ["Penicillin", "Aspirin and NSAIDs", "Pollen", "Dust mite"], 1, "Aspirin exacerbated respiratory disease combines polyps, asthma and NSAID respiratory reactions from arachidonic shunting to leukotrienes; aspirin desensitisation helps selected specialist cases.", ["Incorrect. Penicillin allergy is separate drug reaction.", "Correct. Aspirin and NSAID sensitivity completes triad.", "Incorrect. Pollen drives seasonal rhinitis.", "Incorrect. Mite drives perennial allergy without triad."], "Polyps, wheeze and aspirin do not mix."),
  mcq("bk2-ent-115", "Single unilateral polyp in a 16 year old arising through choana most likely is what?", ["Ethmoid polyp bilateral type", "Antrochoanal polyp", "Inverted papilloma", "Angiofibroma"], 1, "Antrochoanal polyps grow singly from maxillary antrum through accessory ostium into choana in adolescents, causing unilateral obstruction and requiring surgical removal with antral widening. Inverted papilloma favours older adults.", ["Incorrect. Ethmoid polyps are bilateral adult disease.", "Correct. Solitary choanal polyp of youth is antrochoanal.", "Incorrect. Papilloma is older adult lateral wall tumour.", "Incorrect. Angiofibroma bleeds vascularly in males."], "One polyp through back of young nose: antrochoanal."),
  mcq("bk2-ent-116", "Chronic rhinosinusitis duration threshold is symptoms beyond how long?", ["2 weeks", "12 weeks", "3 days", "1 year exactly"], 1, "Twelve weeks of nasal blockage, discharge, facial pain or smell loss (two or more, one being blockage or discharge) defines chronic rhinosinusitis, versus acute viral (under 10 days) and acute bacterial patterns.", ["Incorrect. Two weeks is prolonged acute course.", "Correct. Twelve weeks makes it chronic.", "Incorrect. Three days is common cold onset.", "Incorrect. Year overshoots definition."], "Twelve weeks of sinus symptoms equals chronic."),
  mcq("bk2-ent-117", "Severe recurrent polyps with asthma failing steroids and surgery may receive specialist therapy with what class?", ["Long term antibiotics only", "Biologics targeting type 2 inflammation (IgE, IL4, IL5 pathways)", "More decongestants", "Repeated cautery"], 1, "Monoclonal biologics against IgE, IL4 receptor or IL5 pathways shrink type 2 polyps and reduce surgery and steroid need in selected severe patients under specialist criteria.", ["Incorrect. Antibiotics do not modify polyp biology.", "Correct. Type 2 biologics for severe polyps.", "Incorrect. Decongestants worsen mucosa long term.", "Incorrect. Cautery treats bleeding points, not polyps."], "When polyps keep returning, block type 2 signals."),
  mcq("bk2-ent-118", "Intranasal steroid spray technique should aim the nozzle how and why?", ["At septum for absorption", "Outward laterally to avoid septal irritation and bleeding", "Upward to brain", "Inward crossed hands septally"], 1, "Aiming laterally (same hand to same nostril pointing out, or opposite hand technique per teaching) coats turbinates and avoids septal crusting, epistaxis and perforation from chronic septal jet.", ["Incorrect. Septal jet causes bleeding and perforation.", "Correct. Aim outward to turbinates.", "Incorrect. Upward wastes dose and irritates.", "Incorrect. Crossed aiming still hits septum if pointed in."], "Spray out, not at the septum."),
  mcq("bk2-ent-119", "Allergen immunotherapy is best reserved for which allergic rhinitis patients?", ["Mild intermittent controlled on sprays", "Severe disease with proven dominant allergen failing pharmacotherapy", "All infants", "Non allergic rhinitis"], 1, "Immunotherapy modifies IgE disease over years for severe patients with demonstrable dominant allergen (pollen, mite) inadequately controlled or intolerant of drugs, after specialist assessment for asthma stability.", ["Incorrect. Controlled mild disease needs no years of injections.", "Correct. Severe proven allergen disease failing drugs.", "Incorrect. Infants are not candidates.", "Incorrect. No allergen means no immunotherapy target."], "Years of shots only for severe proven allergy."),
  mcq("bk2-ent-120", "Unilateral nasal mass in 60 year old with epistaxis needs exclusion of which lesions first?", ["Bilateral ethmoid polyps", "Inverted papilloma and malignancy", "Allergic turbinate swelling", "Simple rhinitis"], 1, "One sided masses in older adults include inverted papilloma (locally invasive, malignant potential) and squamous carcinoma, mandating imaging and endoscopic biopsy pathway unlike bilateral benign polyps.", ["Incorrect. Bilateral polyps do not explain unilateral mass.", "Correct. Papilloma and cancer must be excluded.", "Incorrect. Turbinate swelling is mucosal and shrinks.", "Incorrect. Rhinitis causes no unilateral mass."], "One sided mass in older nose: tumour until proven otherwise.")]);


